// 固定真实A+B+C候选5f200f508的C独立18成员；不是业务执行结果。
const C = {
  "packages/brain/scripts/coding-workflow/__tests__/build-materials.test.mjs": "import { describe,it,expect,beforeEach,afterEach } from 'vitest';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { materialFixture, hash } from './helpers/material-fixture.mjs';\nimport { runActivityProcess } from './helpers/run-activity.mjs';\nimport { parseMaterialRecord } from '../lib/material-sync.mjs';\nconst build=fileURLToPath(new URL('../activities/build.mjs',import.meta.url));\nconst chain=fileURLToPath(new URL('../activities/chain-check.mjs',import.meta.url));\nconst cli=fileURLToPath(new URL('./fixtures/fake-claude.mjs',import.meta.url));\nlet f, artifacts;\nbeforeEach(()=>{f=materialFixture();\n  const impl=f.plan.materials.find(r=>r.ref_id==='implementation');\n  impl.additional_changes=['src/feature.js','src/feature.test.js','src/precheck-fixed.txt'].map(path=>({path,action:'update',reason:'构建与预检修复',verification:'检查实际diff'}));\n  f.record.materials.push(...impl.additional_changes.map(row=>({...row,ref_id:impl.ref_id,command:'git diff --stat',output:'checked'})));\n  const specPath=path.join(f.dir,'02-spec.md');const spec=fs.readFileSync(specPath,'utf8').replace(/```json\\n[\\s\\S]*?\\n```/, '```json\\n'+JSON.stringify(f.plan)+'\\n```');fs.writeFileSync(specPath,spec);f.input.spec_sha256=hash(spec);f.record.spec_sha256=hash(spec);\n  artifacts=fs.mkdtempSync(path.join(os.tmpdir(),'cw-build-record-'));fs.chmodSync(cli,0o755)});\nafterEach(()=>{f.cleanup();fs.rmSync(artifacts,{recursive:true,force:true})});\nasync function run(stale=false){\n  const file=path.join(artifacts,'record.json');fs.writeFileSync(file,JSON.stringify(f.record));\n  const env={CODING_WF_PROVIDER:'claude',CODING_WF_CLAUDE_BIN:cli,FAKE_CLAUDE_MODE:'build-ok',FAKE_CLAUDE_MODE_PRECHECK:'precheck-fix',FAKE_MATERIAL_RECORD:file,\n    FAKE_KEEP_STALE_MATERIAL_RECORD:stale?'1':'0',FAKE_PROMPT_LOG:path.join(artifacts,'prompt.txt'),\n    CODING_WF_PRECHECKS:JSON.stringify([{name:'needs-fix',cmd:['bash','-c','test -f src/precheck-fixed.txt']}])};\n  const r=await runActivityProcess(build,f.input,env);\n  expect(r.exitCode,r.stderr+JSON.stringify(r.result)).toBe(0);\n  expect(r.result.outputs.ci_precheck.rounds).toBe(1);\n  return {r,c:await runActivityProcess(chain,{...f.input,...r.result.outputs})};\n}\ndescribe('build预检修复与材料记录接缝',()=>{\n  it('真实修复追加提交后03绑定新候选并通过可信chain-check',async()=>{\n    const {r,c}=await run();\n    expect(c.exitCode,c.stderr+JSON.stringify(c.result)).toBe(0);\n    expect(parseMaterialRecord(fs.readFileSync(path.join(f.dir,'03-build.md'),'utf8')).candidate_sha).toBe(r.result.outputs.candidate_sha);\n    expect(fs.readFileSync(path.join(artifacts,'prompt.txt'),'utf8')).toContain('仅允许更新 03-build.md');\n  });\n  it('真实修复提交后保留旧03，即使buildhash是新读的也被拒绝',async()=>{\n    const {c}=await run(true);\n    expect(c.exitCode).toBe(2);\n    expect(c.result.outputs.material_sync.unresolved).toContain('material_record_candidate_mismatch');\n  });\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/build.test.mjs": "import { describe, it, expect, beforeAll, beforeEach, afterEach } from 'vitest';\nimport crypto from 'node:crypto';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { parseFrontmatter } from '../lib/md-chain.mjs';\nimport { runActivityProcess } from './helpers/run-activity.mjs';\nimport { git, gitPlain, initCommittableRepo } from './helpers/git.mjs';\n\nconst HERE = path.dirname(fileURLToPath(import.meta.url));\nconst ENTRY = path.join(HERE, '../activities/build.mjs');\nconst FAKE_CLAUDE = path.join(HERE, 'fixtures/fake-claude.mjs');\nconst TASK_ID = '11111111-2222-3333-4444-555555555555';\nconst SPEC = `---\\ntask_id: ${TASK_ID}\\nstep: spec\\nupstream: [\"01-intent.md#I-1\"]\\n---\\n# spec\\n\\n### S-1\\n一\\n\\n### S-2\\n二\\n`;\n\ndescribe('build 活动（子进程 + 假 claude + 真实 git 提交）', () => {\n  let root;\n  let worktree;\n  let sprintAbs;\n\n  beforeAll(() => {\n    fs.chmodSync(FAKE_CLAUDE, 0o755);\n  });\n  beforeEach(() => {\n    root = fs.mkdtempSync(path.join(os.tmpdir(), 'build-test-'));\n    worktree = path.join(root, 'wt');\n    fs.mkdirSync(worktree);\n    initCommittableRepo(worktree, path.join(root, 'no-hooks'));\n    sprintAbs = path.join(worktree, 'sprints/s1');\n    fs.mkdirSync(sprintAbs, { recursive: true });\n    fs.writeFileSync(path.join(sprintAbs, '01-intent.md'), '# intent\\n');\n    fs.writeFileSync(path.join(sprintAbs, '02-spec.md'), SPEC);\n  });\n  afterEach(() => {\n    fs.rmSync(root, { recursive: true, force: true });\n  });\n\n  const input = (patch = {}) => ({\n    run_tag: 'rt-1',\n    task_id: TASK_ID,\n    worktree,\n    sprint_dir: 'sprints/s1',\n    spec_file: '02-spec.md',\n    ...patch,\n  });\n  const run = (mode, patch, extraEnv = {}) =>\n    runActivityProcess(ENTRY, input(patch), { CODING_WF_PROVIDER: 'claude', CODING_WF_CLAUDE_BIN: FAKE_CLAUDE, FAKE_CLAUDE_MODE: mode, ...extraEnv });\n  const buildFile = () => path.join(sprintAbs, '03-build.md');\n  const head = () => git(worktree, 'rev-parse', 'HEAD').trim();\n\n  it('build 模型不能先提交控制器来源索引再让publish登记洗白', async () => {\n    const r = await run('build-ok', {}, { FAKE_BUILD_EXTRA_FILE: '.implementation-source-relations.json' });\n    expect(r.result.status).toBe('failed');\n    expect(r.result.reason_code).toBe('build_touched_controlled_metadata');\n    expect(r.result.evidence).toEqual([{ files: ['.implementation-source-relations.json'] }]);\n  });\n\n  it('build-ok：completed，outputs 带 03-build.md 与新提交 SHA，03 覆盖全部 S-n', async () => {\n    const before = head();\n    const r = await run('build-ok');\n    expect(r.exitCode, r.stderr).toBe(0);\n    expect(r.result.failure_class).toBeNull();\n    expect(r.stdout.trim().split('\\n')).toHaveLength(1);\n    const sha = head();\n    expect(sha).not.toBe(before);\n    // 临时仓库里没有 CI 门禁脚本、也没有 origin/main：默认预检全部跳过，记为通过\n    expect(r.result.outputs).toEqual({ build_file: '03-build.md', build_commits: [sha], candidate_sha: sha, build_sha256: crypto.createHash('sha256').update(fs.readFileSync(buildFile())).digest('hex'), ci_precheck: { passed: true, rounds: 0, failures: [] } });\n\n    const fm = parseFrontmatter(fs.readFileSync(buildFile(), 'utf8'));\n    expect(fm.data).toEqual({ task_id: TASK_ID, step: 'build', upstream: ['02-spec.md#S-1', '02-spec.md#S-2'] });\n    expect(git(worktree, 'show', '--name-only', '--format=', 'HEAD').trim().split('\\n').sort())\n      .toEqual(['src/feature.js', 'src/feature.test.js']);\n  });\n\n  it('claude 参数：acceptEdits，允许 Bash，禁 git push 与 gh；prompt 带 S-n 列表与 03 路径', async () => {\n    const r = await run('build-ok');\n    expect(r.stderr).toContain(\n      'FAKE_ARGS: -p --permission-mode acceptEdits --allowedTools Bash --disallowedTools Bash(git push:*) Bash(gh:*)',\n    );\n    expect(r.stderr).toMatch(/FAKE_ARGS: .* --model opus\\n/);\n    expect(r.stderr).toContain(`FAKE_CWD: ${fs.realpathSync(worktree)}`);\n  });\n\n  it('真实 build 子进程收到可读取的原始 intent 绝对路径，任务禁止项不在渲染中丢失', async () => {\n    const intent = '# 文档任务\\n\\n仅改 README.md；不改程序、测试，不新增镜像单元测试。\\n';\n    fs.writeFileSync(path.join(sprintAbs, '01-intent.md'), intent);\n    const contextFile = path.join(root, 'build-context.json');\n    const r = await run('build-ok', {}, { FAKE_BUILD_CONTEXT_FILE: contextFile });\n    expect(r.exitCode, r.stderr).toBe(0);\n    const context = JSON.parse(fs.readFileSync(contextFile, 'utf8'));\n    expect(context.intent_path).toBe(path.join(sprintAbs, '01-intent.md'));\n    expect(path.isAbsolute(context.intent_path)).toBe(true);\n    expect(context.intent).toBe(intent);\n    expect(context.spec_path).toBe(path.join(sprintAbs, '02-spec.md'));\n    // 这里只证明真实输入传递，不把假 CLI 的输出当作模型遵守文件范围的证据。\n  });\n\n  it('多个提交按时间顺序（旧→新）全部列出', async () => {\n    const r = await run('build-ok', {}, { FAKE_BUILD_COMMITS: '3' });\n    expect(r.exitCode, r.stderr).toBe(0);\n    const expected = git(worktree, 'rev-list', '--reverse', 'HEAD~3..HEAD').trim().split('\\n');\n    expect(expected).toHaveLength(3);\n    expect(r.result.outputs.build_commits).toEqual(expected);\n  });\n\n  it('build-nocommit：HEAD 未前进 -> fatal build_no_commit', async () => {\n    const r = await run('build-nocommit');\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('build_no_commit');\n  });\n\n  it('build-dirty：运行后留有未提交改动 -> fatal build_uncommitted，evidence 列出文件', async () => {\n    const r = await run('build-dirty');\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('build_uncommitted');\n    expect(r.result.evidence).toEqual([{ uncommitted_changes: ['src/dirty.js'] }]);\n  });\n\n  it('build-noreport：没写 03-build.md -> fatal build_report_missing', async () => {\n    const r = await run('build-noreport');\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('build_report_missing');\n  });\n\n  it('旧 03-build.md 残留 + 本次没写 -> build_report_missing（运行前先删旧文件）', async () => {\n    fs.writeFileSync(buildFile(), '# stale\\n');\n    const r = await run('build-noreport');\n    expect(r.result.reason_code).toBe('build_report_missing');\n    expect(fs.existsSync(buildFile())).toBe(false);\n  });\n\n  it('运行前已存在的无关脏文件、sprint 目录内的改动都不算未提交改动', async () => {\n    fs.writeFileSync(path.join(worktree, 'pre-existing.txt'), 'dirty\\n');\n    const r = await run('build-ok');\n    expect(r.exitCode, r.stderr).toBe(0);\n    expect(git(worktree, 'status', '--porcelain', '--', 'sprints')).toContain('sprints/');\n  });\n\n  it('02-spec.md 不存在 -> fatal spec_missing，不启动 claude', async () => {\n    fs.rmSync(path.join(sprintAbs, '02-spec.md'));\n    const r = await run('build-ok');\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('spec_missing');\n    expect(r.stderr).not.toContain('FAKE_CWD');\n  });\n\n  it('02-spec.md 没有任何 S-n -> fatal spec_ids_missing，不启动 claude', async () => {\n    fs.writeFileSync(path.join(sprintAbs, '02-spec.md'), `---\\ntask_id: ${TASK_ID}\\nstep: spec\\nupstream: []\\n---\\n# 空\\n`);\n    const r = await run('build-ok');\n    expect(r.result.reason_code).toBe('spec_ids_missing');\n    expect(r.stderr).not.toContain('FAKE_CWD');\n  });\n\n  it('worktree 不是 git 仓库 -> fatal git_head_unavailable，不启动 claude', async () => {\n    fs.rmSync(path.join(worktree, '.git'), { recursive: true, force: true });\n    const r = await run('build-ok');\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('git_head_unavailable');\n    expect(r.stderr).not.toContain('FAKE_CWD');\n  });\n\n  it('sprint_dir 非法 -> fatal sprint_dir_invalid', async () => {\n    const r = await run('build-ok', { sprint_dir: '../x' });\n    expect(r.result.reason_code).toBe('sprint_dir_invalid');\n  });\n\n  describe('防篡改与防误操作', () => {\n    const sha = (file) => crypto.createHash('sha256').update(fs.readFileSync(path.join(sprintAbs, file))).digest('hex');\n    const hashes = () => ({ intent_sha256: sha('01-intent.md'), spec_sha256: sha('02-spec.md') });\n\n    it('哈希与上下文一致 -> 正常 completed', async () => {\n      const r = await run('build-ok', hashes());\n      expect(r.exitCode, r.stderr).toBe(0);\n    });\n\n    it('claude 改了 02-spec.md -> fatal chain_tampered，evidence 指出文件', async () => {\n      const r = await run('build-ok', hashes(), { FAKE_TAMPER_FILE: 'sprints/s1/02-spec.md' });\n      expect(r.result.failure_class).toBe('fatal');\n      expect(r.result.reason_code).toBe('chain_tampered');\n      expect(r.result.evidence).toEqual([{ tampered_files: ['02-spec.md'] }]);\n    });\n\n    it('本次提交触及 sprint 目录 -> fatal chain_tampered，evidence 列出被提交的 sprint 文件', async () => {\n      const r = await run('build-ok', hashes(), { FAKE_BUILD_EXTRA_FILE: 'sprints/s1/notes.md' });\n      expect(r.result.reason_code).toBe('chain_tampered');\n      expect(r.result.evidence).toEqual([{ committed_sprint_files: ['sprints/s1/notes.md'] }]);\n    });\n\n    it('build 期间远端分支变了（被推送）-> fatal remote_changed，evidence 带前后远端 SHA', async () => {\n      const origin = path.join(root, 'origin.git');\n      gitPlain('init', '--bare', '-q', origin);\n      git(worktree, 'remote', 'add', 'origin', origin);\n      const r = await run('build-ok', {}, { FAKE_PUSH: '1' });\n      expect(r.result.failure_class).toBe('fatal');\n      expect(r.result.reason_code).toBe('remote_changed');\n      expect(r.result.evidence).toEqual([{ remote_before: '', remote_after: head() }]);\n    });\n\n    it('origin 已配置但 ls-remote 失败（重试后仍失败）-> retryable remote_check_failed，不启动 claude', async () => {\n      git(worktree, 'remote', 'add', 'origin', path.join(root, 'no-such-origin.git'));\n      const r = await run('build-ok');\n      expect(r.result.failure_class).toBe('retryable');\n      expect(r.result.reason_code).toBe('remote_check_failed');\n      expect(r.stderr).not.toContain('FAKE_CWD');\n    });\n\n    it('claude 子进程拿不到 GH 令牌，GIT_TERMINAL_PROMPT=0', async () => {\n      const r = await run('build-ok', {}, { GH_TOKEN: 'secret', GITHUB_TOKEN: 'secret' });\n      expect(r.stderr).toContain('GH_TOKEN=<unset> GITHUB_TOKEN=<unset> GH_ENTERPRISE_TOKEN=<unset> GIT_TERMINAL_PROMPT=0');\n      expect(r.stderr).toContain('FAKE_GH_CONFIG_EMPTY: true');\n    });\n\n    it('build-amend：运行前的 HEAD 不再是祖先 -> fatal build_history_rewritten', async () => {\n      const before = head();\n      const r = await run('build-amend');\n      expect(r.result.failure_class).toBe('fatal');\n      expect(r.result.reason_code).toBe('build_history_rewritten');\n      expect(r.result.evidence[0]).toMatchObject({ head_before: before, head_after: head() });\n    });\n\n    it('build 期间切了分支 -> fatal build_history_rewritten，evidence 带前后分支', async () => {\n      const r = await run('build-ok', {}, { FAKE_SWITCH_BRANCH: 'cp-1008000000-other' });\n      expect(r.result.reason_code).toBe('build_history_rewritten');\n      expect(r.result.evidence[0]).toMatchObject({ branch_before: 'cp-1008000000-test', branch_after: 'cp-1008000000-other' });\n    });\n\n    it.each(['CLAUDE.md', '.claude/settings.json', 'docs/AGENTS.md'])(\n      '本次提交触及 agent 配置 %s -> fatal build_touched_agent_config',\n      async (file) => {\n        const r = await run('build-ok', {}, { FAKE_BUILD_EXTRA_FILE: file });\n        expect(r.result.failure_class).toBe('fatal');\n        expect(r.result.reason_code).toBe('build_touched_agent_config');\n        expect(r.result.evidence).toEqual([{ files: [file] }]);\n      },\n    );\n\n    it.each(['sprints/s1/CLAUDE.md', 'sprints/s1/notes.md'])(\n      'sprint 目录里出现 03-build.md 以外的新文件 %s -> fatal build_sprint_polluted',\n      async (file) => {\n        const r = await run('build-ok', {}, { FAKE_TAMPER_FILE: file });\n        expect(r.result.failure_class).toBe('fatal');\n        expect(r.result.reason_code).toBe('build_sprint_polluted');\n        expect(r.result.evidence).toEqual([{ files: [file] }]);\n      },\n    );\n\n    it('build-badreport：03 的 upstream 没覆盖全部 S-n -> fatal build_report_invalid', async () => {\n      const r = await run('build-badreport');\n      expect(r.result.failure_class).toBe('fatal');\n      expect(r.result.reason_code).toBe('build_report_invalid');\n      expect(r.result.evidence[0].errors).toContain('not_covered:S-2');\n    });\n\n    it('03 没有 frontmatter -> fatal build_report_invalid', async () => {\n      const r = await run('build-noreport', {}, { FAKE_TAMPER_FILE: 'sprints/s1/03-build.md' });\n      expect(r.result.reason_code).toBe('build_report_invalid');\n      expect(r.result.evidence[0].errors).toContain('frontmatter_missing');\n    });\n  });\n\n  // 审计 P1 #4：推上去之前先在本地跑 CI 规矩类门禁，红了带日志退回修（最多 2 轮），修完重新过后置检查\n  describe('CI 门禁本地预检（ci_precheck）', () => {\n    const FIXED = 'src/precheck-fixed.txt';\n    // 用例里换掉默认门禁清单（真实脚本在临时仓库里不存在）；01 默认标题 intent 不以修复开头 → feature\n    const checks = (list) => ({ CODING_WF_PRECHECKS: JSON.stringify(list) });\n    const needsFix = { name: 'lint-feature-has-smoke', cmd: ['bash', '-c', `test -f ${FIXED} || { echo \"feat PR 改了 brain/src 必须新增 smoke 脚本\"; exit 1; }`] };\n\n    it('全部门禁通过 → completed，outputs.ci_precheck passed、0 轮修复，不起修复会话', async () => {\n      const r = await run('build-ok', {}, checks([{ name: 'ok', cmd: ['true'] }]));\n      expect(r.result.status, r.stderr).toBe('completed');\n      expect(r.result.outputs.ci_precheck).toEqual({ passed: true, rounds: 0, failures: [] });\n      expect(r.stdout).not.toContain('FAKE_ROLE: ci_precheck_fix');\n    });\n\n    it('门禁红 → 修复会话拿到失败项与日志 → 提交修复 → 重跑通过；修复提交计入 build_commits', async () => {\n      const r = await run('build-ok', {}, { ...checks([needsFix]), FAKE_CLAUDE_MODE_PRECHECK: 'precheck-fix', FAKE_PROMPT_LOG: path.join(root, 'precheck-prompt.txt') });\n      expect(r.result.status, r.stderr).toBe('completed');\n      expect(r.result.outputs.ci_precheck).toEqual({ passed: true, rounds: 1, failures: [] });\n      expect(r.result.outputs.build_commits).toHaveLength(2);\n      expect(git(worktree, 'log', '-1', '--format=%s').trim()).toBe('fix: CI 门禁预检');\n      const prompt = fs.readFileSync(path.join(root, 'precheck-prompt.txt'), 'utf8');\n      expect(prompt).toContain('lint-feature-has-smoke');\n      expect(prompt).toContain('必须新增 smoke 脚本');\n    });\n\n    it('修 2 轮仍红 → 照常 completed，ci_precheck 标明未过的门禁（交 CI 与 CI 修复环兜底，不卡死链路）', async () => {\n      const r = await run('build-ok', {}, { ...checks([needsFix]), FAKE_CLAUDE_MODE_PRECHECK: 'precheck-noop' });\n      expect(r.result.status, r.stderr).toBe('completed');\n      expect(r.result.outputs.ci_precheck).toEqual({ passed: false, rounds: 2, failures: ['lint-feature-has-smoke'] });\n    });\n\n    it('修复会话改了 sprint 目录 → fatal（同 build 的后置检查）', async () => {\n      const r = await run('build-ok', {}, { ...checks([needsFix]), FAKE_CLAUDE_MODE_PRECHECK: 'precheck-sprint' });\n      expect(r.result.failure_class).toBe('fatal');\n      expect(['chain_tampered', 'build_sprint_polluted']).toContain(r.result.reason_code);\n    });\n\n    // feature 判定按 publish 的 PR 标题：01 标题不以修复开头 → 门禁拿到 PR_LABELS=feature；以修复开头 → 空\n    const probe = [{ name: 'probe', cmd: ['bash', '-c', '[ \"$PR_LABELS\" = feature ]'] }];\n    it.each([['# 新增 status 页\\n', true], ['# 修复 Brain 非法 id\\n', false]])('01 标题 %j → 门禁看到 feature=%s', async (heading, feature) => {\n      fs.writeFileSync(path.join(sprintAbs, '01-intent.md'), heading);\n      const r = await run('build-ok', {}, { ...checks(probe), FAKE_CLAUDE_MODE_PRECHECK: 'precheck-noop' });\n      expect(r.result.outputs?.ci_precheck?.passed, JSON.stringify(r.result)).toBe(feature);\n    });\n  });\n\n  it('claude 鉴权失败 -> needs_human claude_auth', async () => {\n    const r = await run('auth');\n    expect(r.result.failure_class).toBe('needs_human');\n    expect(r.result.reason_code).toBe('claude_auth');\n  });\n\n  it('claude 其他非 0 -> retryable claude_failed', async () => {\n    const r = await run('fail');\n    expect(r.result.failure_class).toBe('retryable');\n    expect(r.result.reason_code).toBe('claude_failed');\n  });\n\n  it('claude 超时（CODING_WF_BUILD_TIMEOUT_MS）-> retryable claude_timeout', async () => {\n    const started = Date.now();\n    const r = await run('sleep', {}, { CODING_WF_BUILD_TIMEOUT_MS: '1500' });\n    expect(r.result.failure_class).toBe('retryable');\n    expect(r.result.reason_code).toBe('claude_timeout');\n    expect(Date.now() - started).toBeLessThan(10000);\n  });\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/chain-materials.test.mjs": "import { describe,it,expect,beforeEach,afterEach } from 'vitest';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { runActivityProcess } from './helpers/run-activity.mjs';\nimport { materialFixture, hash } from './helpers/material-fixture.mjs';\nimport { git } from './helpers/git.mjs';\nconst entry=fileURLToPath(new URL('../activities/chain-check.mjs',import.meta.url));\nlet f;\nbeforeEach(()=>{f=materialFixture()});afterEach(()=>f.cleanup());\nconst run=()=>runActivityProcess(entry,f.input);\ndescribe('可信chain-check材料核对',()=>{\n  it('真实活动读取固定Git与受保护02/03，交出候选与材料核验事实',async()=>{\n    const r=await run();expect(r.exitCode,r.stderr+JSON.stringify(r.result)).toBe(0);\n    expect(r.result.outputs.material_sync).toMatchObject({status:'verified',base_sha:f.base,candidate_sha:f.candidate,unresolved:[],unmapped_changes:[]});\n    expect(r.result.outputs.material_sync.materials).toHaveLength(4);\n  });\n  it('hash已登记的02或03被改后失败，不以新内容自签',async()=>{\n    fs.appendFileSync(path.join(f.dir,'03-build.md'),'changed');\n    const r=await run();expect(r.exitCode).toBe(2);expect(r.result.reason_code).toBe('chain_tampered');\n  });\n  it('模型03谎报正确但真实保留材料变了仍失败',async()=>{\n    fs.writeFileSync(path.join(f.root,'spec.md'),'unexpected');git(f.root,'add','spec.md');git(f.root,'commit','-qm','unplanned');\n    f.input.candidate_sha=git(f.root,'rev-parse','HEAD').trim();f.record.candidate_sha=f.input.candidate_sha;f.writeRecord();f.input.build_sha256=hash(fs.readFileSync(path.join(f.dir,'03-build.md')));\n    const r=await run();expect(r.exitCode).toBe(2);expect(r.result.reason_code).toBe('material_sync_invalid');\n    expect(r.result.outputs.material_sync.unresolved).toContain('material_keep_changed:spec.md');\n  });\n  it('旧候选的03即使有新hash仍因candidate绑定不符而失败',async()=>{\n    f.record.candidate_sha=f.base;f.writeRecord();f.input.build_sha256=hash(fs.readFileSync(path.join(f.dir,'03-build.md')));\n    const r=await run();expect(r.exitCode).toBe(2);expect(r.result.outputs.material_sync.unresolved).toContain('material_record_candidate_mismatch');\n  });\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/e2e-contract.test.mjs": "// 端到端：main 上的通用执行器 activity-contract-run.js 跑完整八活动契约。\n// 假 claude / 假 gh / 本地假 Brain / 临时 bare origin，全程不碰真实服务。\nimport { describe, it, expect, beforeAll, beforeEach, afterEach } from 'vitest';\nimport { startTestBrain } from './helpers/brain-transport.mjs';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { spawn } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\nimport { childEnv } from '../lib/protocol.mjs';\nimport { git, gitPlain } from './helpers/git.mjs';\n\nconst HERE = path.dirname(fileURLToPath(import.meta.url));\nconst WORKFLOW_DIR = path.join(HERE, '..');\nconst RUNNER = path.join(HERE, '../../activity-contract-run.js');\nconst FAKE_CLAUDE = path.join(HERE, 'fixtures/fake-claude.mjs');\nconst FAKE_GH = path.join(HERE, 'fixtures/fake-gh.mjs');\nconst contract = JSON.parse(fs.readFileSync(path.join(WORKFLOW_DIR, 'contract.json'), 'utf8'));\n\nconst TASK_ID = '11111111-2222-3333-4444-555555555555';\nconst BRANCH = 'cp-1007220300-coding-workflow-e2e';\nconst ACTIVITY_KEYS = ['intent', 'spec', 'spec_review', 'build', 'verify', 'chain_check', 'publish', 'report'];\nconst CHAIN_FILES = ['01-intent.md', '02-spec.md', '02-review.md', '03-build.md', '04-evidence.md'];\n\n/** 以子进程运行 CLI：stdin 写 JSON，返回 { exitCode, stdout, stderr, result }。 */\nfunction runCli(envelope, env, transport) {\n  return new Promise((resolve, reject) => {\n    const preloads = [...transport.args];\n    if (preloads.length) {\n      const relay = new URL('../runner/__tests__/fixtures/executor-ipc-preload.mjs', import.meta.url);\n      relay.searchParams.set('fetchPreload', preloads[1]);\n      for (const activity of contract.activities) relay.searchParams.append('activity', path.resolve(WORKFLOW_DIR, activity.runtime.entry));\n      preloads.push('--import', relay.href);\n    }\n    const child = spawn(process.execPath, [...preloads, RUNNER, '--cwd', WORKFLOW_DIR], {\n      env,\n      stdio: transport.stdio,\n    });\n    transport.attach(child);\n    let stdout = '';\n    let stderr = '';\n    child.stdout.setEncoding('utf8');\n    child.stderr.setEncoding('utf8');\n    child.stdout.on('data', (d) => { stdout += d; });\n    child.stderr.on('data', (d) => { stderr += d; });\n    child.on('error', reject);\n    child.on('close', (exitCode) => {\n      let result = null;\n      try {\n        result = JSON.parse(stdout);\n      } catch {\n        result = null;\n      }\n      resolve({ exitCode, stdout, stderr, result });\n    });\n    child.stdin.end(JSON.stringify(envelope));\n  });\n}\n\ndescribe('coding_spec 八活动契约端到端（通用执行器 + 假外部依赖）', () => {\n  let root;\n  let worktree;\n  let origin;\n  let server;\n  let brainUrl;\n  let patches;\n  let ghLog;\n\n  beforeAll(() => {\n    fs.chmodSync(FAKE_CLAUDE, 0o755);\n    fs.chmodSync(FAKE_GH, 0o755);\n  });\n\n  beforeEach(async () => {\n    root = fs.mkdtempSync(path.join(os.tmpdir(), 'cw-e2e-'));\n    worktree = path.join(root, 'worktree');\n    origin = path.join(root, 'origin.git');\n    ghLog = path.join(root, 'gh.log');\n    const emptyHooks = path.join(root, 'no-hooks');\n    fs.mkdirSync(emptyHooks);\n    fs.mkdirSync(worktree);\n\n    gitPlain('init', '--bare', '-q', origin);\n    gitPlain('init', '-q', worktree);\n    git(worktree, 'checkout', '-q', '-b', BRANCH);\n    git(worktree, 'config', 'user.name', 'e2e');\n    git(worktree, 'config', 'user.email', 'e2e@example.com');\n    // 本机全局 pre-commit 钩子要求 .dev-mode.<branch>；同时把 hooksPath 指向空目录避免钩子干扰\n    git(worktree, 'config', 'core.hooksPath', emptyHooks);\n    fs.writeFileSync(path.join(worktree, `.dev-mode.${BRANCH}`), 'e2e\\n');\n    git(worktree, 'remote', 'add', 'origin', origin);\n    git(worktree, 'commit', '-q', '--allow-empty', '-m', 'chore: init');\n\n    patches = [];\n    let task = { id: TASK_ID, title: 'e2e 任务', payload: { acceptance: ['能登录', '能退出'] } };\n    server = await startTestBrain(({ method, url, body }) => {\n      const reply = (data, status = 200) => ({ status, body: JSON.stringify(data) });\n      if (method === 'GET' && url === `/api/brain/tasks/${TASK_ID}`) return reply(task);\n      if (method === 'GET' && url.startsWith('/api/brain/decisions?category=invariant')) {\n        return reply([{ id: '02d8e749-aaaa-4bbb-8ccc-dddddddddddd', topic: '不得缩减已拍板设计', decision: 'GAN 无上限', status: 'active' }]);\n      }\n      if (method === 'PATCH') {\n        patches.push({ url, raw: body });\n        task = { ...task, result: { ...task.result, ...JSON.parse(body).result } };\n        return reply(task);\n      }\n      return reply({}, 404);\n    });\n    brainUrl = server.url;\n  });\n\n  afterEach(async () => {\n    await server.close();\n    fs.rmSync(root, { recursive: true, force: true });\n  });\n\n  const envFor = (verifyMode) => ({\n    ...childEnv(process.env, { stripClaude: true }),\n    CODING_WF_CLAUDE_BIN: FAKE_CLAUDE,\n    FAKE_CLAUDE_MODE: 'ok',\n    FAKE_CLAUDE_MODE_REVIEW: 'review-approve',\n    FAKE_CLAUDE_MODE_BUILD: 'build-ok',\n    FAKE_CLAUDE_MODE_VERIFY: verifyMode,\n    CODING_WF_GH_BIN: FAKE_GH,\n    FAKE_GH_MODE: 'new',\n    FAKE_GH_LOG: ghLog,\n  });\n  const runInput = () => ({\n    run_tag: 'e2e-rt-1',\n    task_id: TASK_ID,\n    worktree,\n    sprint_dir: 'sprints/e2e',\n    brain_url: brainUrl,\n  });\n  const ghCalls = () => (fs.existsSync(ghLog)\n    ? fs.readFileSync(ghLog, 'utf8').trim().split('\\n').filter(Boolean).map((l) => JSON.parse(l))\n    : []);\n\n  it('完整八活动 completed：build 真实提交、verify 全 PASS，PR 正文含验收摘要，Brain 恰好收到一次 PATCH', async () => {\n    const r = await runCli({ contract, input: runInput() }, envFor('verify-pass'), server.spawnOptions());\n\n    expect(r.exitCode, r.stderr).toBe(0);\n    expect(r.result).not.toBeNull();\n    expect(r.result.status).toBe('completed');\n    expect(r.result.run_tag).toBe('e2e-rt-1');\n    expect(r.result.activities.map((a) => a.key)).toEqual(ACTIVITY_KEYS);\n    expect(r.result.activities).toHaveLength(8);\n    for (const a of r.result.activities) expect(a.status, a.key).toBe('completed');\n\n    const publish = r.result.activities.find((a) => a.key === 'publish');\n    const prUrl = publish.attempts.at(-1).outputs.pr_url;\n    expect(prUrl).toBe('https://github.com/example/repo/pull/2');\n\n    // 假 Brain：恰好一次 PATCH，只带 result.coding_workflow，不带 status\n    expect(patches).toHaveLength(1);\n    expect(patches[0].url).toBe(`/api/brain/tasks/${TASK_ID}`);\n    const body = JSON.parse(patches[0].raw);\n    expect('status' in body).toBe(false);\n    expect(Object.keys(body)).toEqual(['result']);\n    expect(body.result.coding_workflow.pr_url).toBe(prUrl);\n    expect(body.result.coding_workflow.branch).toBe(BRANCH);\n    expect(body.result.coding_workflow.sprint_dir).toBe('sprints/e2e');\n    expect(body.result.coding_workflow.chain_files).toEqual(CHAIN_FILES);\n    expect(body.result.coding_workflow.run_tag).toBe('e2e-rt-1');\n\n    // build 的提交与 verify 的验收结果进了上下文\n    const build = r.result.activities.find((a) => a.key === 'build').attempts.at(-1).outputs;\n    expect(build.build_file).toBe('03-build.md');\n    expect(build.build_commits).toHaveLength(1);\n    expect(r.result.outputs.verified_ids).toEqual(['I-1', 'I-2']);\n    // md 链指纹贯穿全程，build/verify 的防篡改检查都实际比对过\n    expect(r.result.outputs.intent_sha256).toMatch(/^[0-9a-f]{64}$/);\n    expect(r.result.outputs.spec_sha256).toMatch(/^[0-9a-f]{64}$/);\n    expect(fs.existsSync(path.join(worktree, 'sprints/e2e/03-build.md'))).toBe(true);\n\n    // PR 正文：md 链 + 每条 I-n 的验收摘要\n    const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');\n    expect(create[create.indexOf('--title') + 1]).toBe('feat(workflow): e2e 任务');\n    const prBody = create[create.indexOf('--body') + 1];\n    expect(prBody).toContain('- sprints/e2e/02-review.md');\n    expect(prBody).toContain('- sprints/e2e/04-evidence.md');\n    expect(prBody).toContain('- I-1：PASS');\n    expect(prBody).toContain('- I-2：PASS');\n\n    // 真实副作用：代码提交与五文件 md 链都已推到 bare origin\n    const pushed = git(origin, 'ls-tree', '-r', '--name-only', BRANCH).trim().split('\\n');\n    expect(pushed).toContain('src/feature.js');\n    for (const f of CHAIN_FILES) expect(pushed).toContain(`sprints/e2e/${f}`);\n    expect(git(origin, 'log', '--format=%H', BRANCH)).toContain(build.build_commits[0]);\n  }, 60000);\n\n  it('verify 判 FAIL：链停在 verify，chain_check/publish 不执行，report 仍执行并把失败证据回写 Brain', async () => {\n    const r = await runCli({ contract, input: runInput() }, envFor('verify-fail'), server.spawnOptions());\n\n    expect(r.result, r.stderr).not.toBeNull();\n    // intent/spec/spec_review/build 已有产出 -> partial（执行器语义），CLI 退出码 2\n    expect(r.result.status).toBe('partial');\n    expect(r.exitCode).toBe(2);\n    expect(r.result.activities.map((a) => a.key)).toEqual(['intent', 'spec', 'spec_review', 'build', 'verify', 'report']);\n\n    const verify = r.result.activities.find((a) => a.key === 'verify');\n    expect(verify.status).toBe('failed');\n    expect(verify.attempts).toHaveLength(1);\n    const attempt = verify.attempts[0];\n    expect(attempt.failure_class).toBe('fatal');\n    expect(attempt.reason_code).toBe('verification_failed');\n    const failure = {\n      failed: [{ id: 'E-2', covers: ['I-2'], command: 'npm test -- I-2', output: 'AssertionError: expected 500 to be 200' }],\n      verdicts: [{ intent: 'I-1', verdict: 'PASS' }, { intent: 'I-2', verdict: 'FAIL' }],\n    };\n    expect(attempt.evidence).toEqual([failure]);\n    expect(r.result.evidence).toContainEqual(failure);\n\n    // verify 的失败结论进了上下文，finalize 的 report 仍执行并把失败条目回写 Brain\n    expect(r.result.outputs.verification.reason_code).toBe('verification_failed');\n    const report = r.result.activities.find((a) => a.key === 'report');\n    expect(report.status).toBe('completed');\n    expect(patches).toHaveLength(1);\n    const cw = JSON.parse(patches[0].raw).result.coding_workflow;\n    expect(cw.status).toBe('failed');\n    expect(cw.run_tag).toBe('e2e-rt-1');\n    expect(cw.sprint_dir).toBe('sprints/e2e');\n    expect(cw.verification.failed).toEqual([\n      { id: 'E-2', covers: ['I-2'], command: 'npm test -- I-2', output_tail: 'AssertionError: expected 500 to be 200' },\n    ]);\n\n    // publish 没有执行：没调 gh，分支没推到 origin\n    expect(ghCalls()).toHaveLength(0);\n    expect(() => git(origin, 'rev-parse', '--verify', `refs/heads/${BRANCH}`)).toThrow();\n    expect(fs.existsSync(path.join(worktree, 'sprints/e2e/04-evidence.md'))).toBe(true);\n  }, 60000);\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/material-sync.test.mjs": "import { describe, it, expect, beforeEach, afterEach } from 'vitest';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { initCommittableRepo, git } from './helpers/git.mjs';\n\nlet root, base;\nconst sha = 'a'.repeat(64);\nbeforeEach(() => {\n  root = fs.mkdtempSync(path.join(os.tmpdir(), 'cw-materials-'));\n  initCommittableRepo(root, path.join(root, '.hooks'));\n  for (const file of ['spec.md', 'sample.json', 'code.mjs']) fs.writeFileSync(path.join(root, file), 'old');\n  git(root, 'add', '.'); git(root, 'commit', '-qm', 'base');\n  base = git(root, 'rev-parse', 'HEAD').trim();\n});\nafterEach(() => fs.rmSync(root, { recursive: true, force: true }));\nfunction commit(file, text = 'new') {\n  fs.writeFileSync(path.join(root, file), text);\n  git(root, 'add', file); git(root, 'commit', '-qm', 'change');\n  return git(root, 'rev-parse', 'HEAD').trim();\n}\nconst row = (ref_id, file, action = 'update', extra = {}) => ({ ref_id, path: file, action, verification: '检查输出', approval_refs: ['I-1'], ...extra });\nfunction input(materials, candidateSha) {\n  return { worktree: root, baseSha: base, candidateSha, taskId: 'task-1', runTag: 'run-1', specSha: sha, sprintDir: 'sprints/s1',\n    plan: { version: 1, materials },\n    record: { version: 1, task_id: 'task-1', run_tag: 'run-1', base_sha: base, candidate_sha: candidateSha, spec_sha256: sha,\n      materials: materials.flatMap((r) => [r, ...(r.additional_changes ?? []).map((a) => ({...a, ref_id:r.ref_id}))]).map((r) => ({ ref_id: r.ref_id, path: r.path, action: r.action, verification: r.verification, command: 'node check.mjs', output: 'checked' })) } };\n}\nasync function check(data) { return (await import('../lib/material-sync.mjs')).checkMaterialSync(data); }\ndescribe('材料与真实Git树核对', () => {\n  it('真实更新与保留通过，返回实际摘要，不把未映射diff当已核实', async () => {\n    const head = commit('code.mjs');\n    const r = await check(input([row('impl', 'code.mjs'), row('spec', 'spec.md', 'keep')], head));\n    expect(r.errors).toEqual([]);\n    expect(r.materials[0]).toMatchObject({ status: 'verified', changed: true });\n    expect(r.materials[0].before_digest).not.toBe(r.materials[0].after_digest);\n    expect(r.unmapped_changes).toEqual([]);\n  });\n  it('keep实际改动和update无实际改动分别失败', async () => {\n    const head = commit('code.mjs');\n    const r = await check(input([row('impl', 'code.mjs', 'keep'), row('spec', 'spec.md')], head));\n    expect(r.errors).toContain('material_keep_changed:code.mjs');\n    expect(r.errors).toContain('material_update_missing:spec.md');\n  });\n  it('新增明确材料可核对，未知实际改动显式暴露', async () => {\n    commit('extra.mjs'); const head = commit('new.mjs');\n    const r = await check(input([row('impl', 'code.mjs', 'keep', { additional_changes: [{path:'extra.mjs',action:'update',verification:'检查新实现'}] })], head));\n    expect(r.errors).toContain('material_unplanned_change:new.mjs');\n    expect(r.unmapped_changes).toEqual(['new.mjs']);\n    const planned = input([row('impl', 'code.mjs', 'keep', { additional_changes: ['extra.mjs','new.mjs'].map(path => ({path,action:'update',verification:'检查新实现'})) })], head);\n    expect((await check(planned)).errors).toEqual([]);\n    expect(r.materials).toHaveLength(2);\n  });\n  it('删除必须明确retire，更新项被删除拒绝', async () => {\n    fs.unlinkSync(path.join(root,'code.mjs')); git(root,'add','code.mjs'); git(root,'commit','-qm','remove');\n    const head=git(root,'rev-parse','HEAD').trim();\n    expect((await check(input([row('impl','code.mjs','retire')],head))).errors).toEqual([]);\n    expect((await check(input([row('impl','code.mjs')],head))).errors).toContain('material_update_deleted:code.mjs');\n  });\n  it('样本更新无批准不通过，明确批准后允许修改预期', async () => {\n    const head=commit('sample.json');\n    const denied=input([row('sample','sample.json','update',{kind:'sample',approval_refs:[]})],head);\n    expect((await check(denied)).errors).toContain('material_approval_missing:sample.json');\n    expect((await check(input([row('sample','sample.json','update',{kind:'sample'})],head))).errors).toEqual([]);\n  });\n  it('旧task/run/候选/spec的03记录拒绝', async () => {\n    const head=commit('code.mjs'); const data=input([row('impl','code.mjs')],head);\n    data.record.task_id='other'; data.record.run_tag='old'; data.record.candidate_sha=base; data.record.spec_sha256='b'.repeat(64);\n    expect((await check(data)).errors).toEqual(expect.arrayContaining(['material_record_task_mismatch','material_record_run_mismatch','material_record_candidate_mismatch','material_record_spec_mismatch']));\n  });\n  it('记录遗漏或额外自报材料拒绝', async () => {\n    const head=commit('code.mjs'); const data=input([row('impl','code.mjs')],head);\n    data.record.materials=[{ref_id:'fake',path:'spec.md',action:'keep',verification:'x',command:'x',output:'x'}];\n    expect((await check(data)).errors).toEqual(expect.arrayContaining(['material_record_missing:code.mjs','material_record_unknown:spec.md']));\n  });\n  it('候选HEAD变化、未提交文件、非祖先基线拒绝', async () => {\n    const candidate=commit('code.mjs'); commit('extra.mjs');\n    expect((await check(input([row('impl','code.mjs')],candidate))).errors).toContain('material_candidate_moved');\n    fs.writeFileSync(path.join(root,'code.mjs'),'dirty');\n    expect((await check(input([row('impl','code.mjs')],git(root,'rev-parse','HEAD').trim()))).errors).toContain('material_worktree_dirty');\n    git(root,'checkout','--','code.mjs'); git(root,'checkout','-qb','other',base); const other=commit('other.mjs'); git(root,'checkout','-q','cp-1008000000-test');\n    const data=input([row('impl','code.mjs')],git(root,'rev-parse','HEAD').trim()); data.baseSha=other; data.record.base_sha=other;\n    expect((await check(data)).errors).toContain('material_base_not_ancestor');\n  });\n  it('symlink与路径逃逸拒绝', async () => {\n    fs.unlinkSync(path.join(root,'code.mjs')); fs.symlinkSync('spec.md',path.join(root,'code.mjs')); git(root,'add','code.mjs'); git(root,'commit','-qm','link');\n    const head=git(root,'rev-parse','HEAD').trim();\n    expect((await check(input([row('impl','code.mjs')],head))).errors).toContain('material_non_regular:code.mjs');\n    expect((await check(input([row('impl','../outside')],head))).errors).toContain('material_path_invalid');\n  });\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/report-materials.test.mjs": "import { describe, it, expect, afterEach } from 'vitest';\nimport { startTestBrain } from './helpers/brain-transport.mjs';\nimport { runActivityProcess } from './helpers/run-activity.mjs';\nimport { fileURLToPath } from 'node:url';\nconst entry = fileURLToPath(new URL('../activities/report.mjs', import.meta.url));\nlet brain;\nafterEach(async () => { await brain?.close(); });\nasync function fixture({ corrupt = false, readFailure = false, previousVersions = undefined, previousWorkflow = {} } = {}) {\n  let state = { id: 'task-1', result: { handoff: { existing: true }, coding_workflow: { keep: 'old', gan: { round_history: [1] }, verification: { trace: 'kept' }, ...(previousVersions ? {versions:previousVersions} : {}), ...previousWorkflow } } };\n  const calls = [];\n  brain = await startTestBrain(({ method, body }) => {\n    calls.push(method);\n    if (method === 'GET') return { status: readFailure ? 500 : 200, body: JSON.stringify(state) };\n    const patch = JSON.parse(body);\n    state.result = { ...state.result, ...patch.result };\n    if (corrupt) delete state.result.coding_workflow.material_sync;\n    return { status: 200, body: JSON.stringify(state) };\n  });\n  const input = { task_id: 'task-1', run_tag: 'run-1', brain_url: brain.url, pr_url: 'https://github.com/x/r/pull/1',\n    initial_base_sha: 'a'.repeat(40), candidate_sha: 'b'.repeat(40), intent_ids: ['I-1'], verified_ids: ['I-1'],\n    gan: { verdict: 'APPROVED' }, verification: { status: 'passed' },\n    material_sync: { status: 'verified', base_sha: 'a'.repeat(40), candidate_sha: 'b'.repeat(40), materials: [], unresolved: [], unmapped_changes: ['extra.mjs'] } };\n  return { input, calls, read: () => state, run: (patch = {}) => runActivityProcess(entry, { ...input, ...patch }, {}, brain.spawnOptions()) };\n}\ndescribe('交接真实读回', () => {\n  it('GET→PATCH→GET保留顶层及嵌套旧字段，并区分候选/验证/合并/部署', async () => {\n    const f=await fixture(); const r=await f.run();\n    expect(r.exitCode,r.stderr).toBe(0);\n    expect(f.calls).toEqual(['GET','PATCH','GET']);\n    const result=f.read().result;\n    expect(result.handoff).toEqual({existing:true});\n    expect(result.coding_workflow.report_history).toContainEqual(expect.objectContaining({verification:{trace:'kept'}}));\n    expect(result.coding_workflow).toMatchObject({keep:'old',gan:{round_history:[1],verdict:'APPROVED'},verification:{status:'passed'},material_sync:f.input.material_sync,\n      versions:{baseline:'a'.repeat(40),candidate:'b'.repeat(40),verified:'b'.repeat(40),merged:'unknown',deployed:'unknown'}});\n  });\n  it('成功PATCH但读回缺材料不报告成功', async () => {\n    const f=await fixture({corrupt:true}); const r=await f.run();\n    expect(r.exitCode).toBe(2);\n    expect(r.result.reason_code).toBe('report_readback_mismatch');\n    expect(r.result.outputs.reported).not.toBe(true);\n  });\n  it('读取既有状态失败不写入，避免把未知旧账覆盖', async () => {\n    const f=await fixture({readFailure:true});const r=await f.run();\n    expect(r.result.reason_code).toBe('brain_unavailable');\n    expect(f.calls).toEqual(['GET']);\n  });\n  it('没有旧字段或独立验证事实时明确unknown，不追认部署', async () => {\n    const f=await fixture();const r=await f.run({material_sync:undefined,initial_base_sha:undefined,candidate_sha:undefined,verified_ids:undefined});\n    expect(r.exitCode).toBe(0);\n    expect(f.read().result.coding_workflow.material_sync).toEqual({status:'unknown',unresolved:['legacy_unconfigured']});\n    expect(f.read().result.coding_workflow.versions).toEqual({baseline:'unknown',candidate:'unknown',verified:'unknown',merged:'unknown',deployed:'unknown'});\n  });\n  it('同候选重报保留已经存在的合并部署事实，不用unknown抹去', async () => {\n    const known={baseline:'a'.repeat(40),candidate:'b'.repeat(40),verified:'b'.repeat(40),merged:'b'.repeat(40),deployed:'b'.repeat(40)};\n    const f=await fixture({previousVersions:known}); const r=await f.run();\n    expect(r.exitCode).toBe(0);expect(f.read().result.coding_workflow.versions).toEqual(known);\n  });\n  it('新候选不继承旧候选合并部署，但旧事实留在version_history', async () => {\n    const known={baseline:'a'.repeat(40),candidate:'b'.repeat(40),verified:'b'.repeat(40),merged:'b'.repeat(40),deployed:'b'.repeat(40)};\n    const f=await fixture({previousVersions:known});const r=await f.run({candidate_sha:'c'.repeat(40),material_sync:undefined,verified_ids:undefined});\n    expect(r.exitCode).toBe(0);const cw=f.read().result.coding_workflow;\n    expect(cw.versions).toMatchObject({candidate:'c'.repeat(40),merged:'unknown',deployed:'unknown',verified:'unknown'});\n    expect(cw.version_history).toContainEqual(known);\n  });\n  it('材料核对失败且未开PR仍落账，不伪装成已验证候选', async () => {\n    const f=await fixture();const r=await f.run({pr_url:undefined,verification:undefined,material_sync:{status:'failed',unresolved:['material_unplanned_change:x']}});\n    expect(r.exitCode).toBe(0);\n    expect(f.read().result.coding_workflow).toMatchObject({status:'failed',material_sync:{status:'failed'},versions:{verified:'unknown'}});\n  });\n\n  it('新候选成功不继承旧候选failed结论，旧结论保留在历史', async () => {\n    const old={status:'failed',verification:{status:'failed',reason_code:'old_failure'},versions:{candidate:'a'.repeat(40)}};\n    const f=await fixture({previousWorkflow:old});const r=await f.run({verification:undefined});\n    expect(r.exitCode).toBe(0);const cw=f.read().result.coding_workflow;\n    expect(cw.status).toBe('completed');expect(cw.verification.status).toBe('passed');\n    expect(cw.verification.reason_code).toBeUndefined();\n    expect(cw.report_history).toContainEqual(expect.objectContaining({candidate:'a'.repeat(40),status:'failed',verification:old.verification}));\n  });\n  it('同候选无新验证字段重报不会清空已知baseline和verified', async () => {\n    const known={baseline:'a'.repeat(40),candidate:'b'.repeat(40),verified:'b'.repeat(40),merged:'unknown',deployed:'unknown'};\n    const f=await fixture({previousVersions:known});const r=await f.run({initial_base_sha:undefined,verified_ids:undefined,verification:undefined,material_sync:undefined});\n    expect(r.exitCode).toBe(0);expect(f.read().result.coding_workflow.versions).toEqual(known);\n  });\n\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/report.test.mjs": "import { describe, it, expect, beforeEach, afterEach } from 'vitest';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { runActivityProcess as runRawActivityProcess } from './helpers/run-activity.mjs';\n\nimport { startTestBrain } from './helpers/brain-transport.mjs';\nconst unknownHandoff = { material_sync: { status: 'unknown', unresolved: ['legacy_unconfigured'] }, versions: { baseline: 'unknown', candidate: 'unknown', verified: 'unknown', merged: 'unknown', deployed: 'unknown' } };\n\nconst ENTRY = path.join(path.dirname(fileURLToPath(import.meta.url)), '../activities/report.mjs');\nconst TASK_ID = '11111111-2222-3333-4444-555555555555';\n\ndescribe('report 活动（子进程 + 假 Brain）', () => {\n  let server;\n  const runActivityProcess = (entry, input, env) => runRawActivityProcess(entry, input, env, server.spawnOptions());\n  let brainUrl;\n  let requests;\n  let reply;\n\n  beforeEach(async () => {\n    requests = [];\n    reply = { status: 200, body: { id: TASK_ID } };\n    let state = { id: TASK_ID, result: {} };\n    server = await startTestBrain((req) => {\n      if (reply.status !== 200) return { status: reply.status, body: reply.raw ?? JSON.stringify(reply.body) };\n      if (req.method === 'GET') return { status: 200, body: JSON.stringify(state) };\n      if (req.method !== 'PATCH') return { status: 405, body: '{}' };\n      requests.push({ method: req.method, url: req.url, headers: req.headers, raw: req.body });\n      state = { ...state, result: { ...state.result, ...JSON.parse(req.body).result } };\n      return { status: 200, body: JSON.stringify(state) };\n    });\n    brainUrl = server.url;\n  });\n\n  afterEach(async () => { await server?.close(); });\n\n  const input = (patch = {}) => ({\n    run_tag: 'rt-1',\n    task_id: TASK_ID,\n    brain_url: brainUrl,\n    pr_url: 'https://github.com/example/repo/pull/2',\n    branch: 'cp-1007220300-coding-workflow',\n    sprint_dir: 'sprints/s1',\n    chain_files: ['01-intent.md', '02-spec.md'],\n    ...patch,\n  });\n\n  it('成功：恰好一次 PATCH，body 只有 result.coding_workflow 且字段齐全、无 status', async () => {\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.exitCode).toBe(0);\n    expect(r.result.status).toBe('completed');\n    expect(r.result.failure_class).toBeNull();\n    expect(r.result.run_tag).toBe('rt-1');\n    expect(r.result.outputs).toEqual({ reported: true });\n\n    expect(requests).toHaveLength(1);\n    const [req] = requests;\n    expect(req.method).toBe('PATCH');\n    expect(req.url).toBe(`/api/brain/tasks/${TASK_ID}`);\n    expect(req.headers['content-type']).toMatch(/application\\/json/);\n    const body = JSON.parse(req.raw);\n    expect(Object.keys(body)).toEqual(['result']);\n    expect(Object.keys(body.result)).toEqual(['coding_workflow']);\n    expect(body.result.coding_workflow).toEqual({\n      status: 'completed', verification: { status: 'unknown' },\n      pr_url: 'https://github.com/example/repo/pull/2',\n      branch: 'cp-1007220300-coding-workflow',\n      sprint_dir: 'sprints/s1',\n      chain_files: ['01-intent.md', '02-spec.md'],\n      run_tag: 'rt-1',\n      host: os.hostname(),\n      ...unknownHandoff,\n    });\n    expect('status' in body).toBe(false);\n  });\n\n  it('stdout 只有一个结果 JSON', async () => {\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.stdout.trim().split('\\n')).toHaveLength(1);\n  });\n\n  it('brain_url 末尾斜杠被规整，task_id 做 URL 编码', async () => {\n    const r = await runActivityProcess(ENTRY, input({ brain_url: `${brainUrl}//`, task_id: 'a/b c' }));\n    expect(r.exitCode).toBe(0);\n    expect(requests[0].url).toBe('/api/brain/tasks/a%2Fb%20c');\n  });\n\n  it.each([404, 400])('Brain %i -> fatal task_not_found', async (status) => {\n    reply = { status, body: { error: 'nope' } };\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.exitCode).toBe(2);\n    expect(r.result.status).toBe('failed');\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('task_not_found');\n  });\n\n  it('失败结果 evidence 带 http_status 与响应体 code', async () => {\n    reply = { status: 404, body: { code: 'task_gone', error: 'nope' } };\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.result.reason_code).toBe('task_not_found');\n    expect(r.result.evidence).toEqual([{ http_status: 404, body_code: 'task_gone' }]);\n  });\n\n  it.each([\n    [500, 'upstream down', 'brain_unavailable'],\n    [401, '{\"error\":\"no code field\"}', 'brain_http_401'],\n  ])('响应体无可解析的 code（HTTP %i）-> evidence 只有 http_status', async (status, raw, reason) => {\n    reply = { status, raw };\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.result.reason_code).toBe(reason);\n    expect(r.result.evidence).toEqual([{ http_status: status }]);\n  });\n\n  it.each([500, 502, 429, 408])('Brain %i -> retryable brain_unavailable', async (status) => {\n    reply = { status, body: { error: 'later' } };\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('retryable');\n    expect(r.result.reason_code).toBe('brain_unavailable');\n  });\n\n  it('Brain 401 -> fatal brain_http_401', async () => {\n    reply = { status: 401, body: { error: 'no' } };\n    const r = await runActivityProcess(ENTRY, input());\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('brain_http_401');\n  });\n\n  it('传输错误（HTTP连接拒绝或IPC未知来源）-> retryable brain_unavailable', async () => {\n    const r = await runActivityProcess(ENTRY, input({ brain_url: 'http://127.0.0.1:1' }));\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('retryable');\n    expect(r.result.reason_code).toBe('brain_unavailable');\n  });\n\n  it.each([undefined, '', null, 42])('缺 pr_url（%j）-> fatal pr_url_missing，请求数 0', async (prUrl) => {\n    const r = await runActivityProcess(ENTRY, input({ pr_url: prUrl }));\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('pr_url_missing');\n    expect(requests).toHaveLength(0);\n  });\n\n  const verification = {\n    status: 'failed',\n    reason_code: 'verification_failed',\n    failed: [{ id: 'E-2', covers: ['I-2'], command: 'npm test', output_tail: 'HTTP 500' }],\n  };\n\n  it('有 pr_url 且有 verification -> verification 一并写入 result.coding_workflow', async () => {\n    const r = await runActivityProcess(ENTRY, input({ verification }));\n    expect(r.exitCode).toBe(0);\n    const cw = JSON.parse(requests[0].raw).result.coding_workflow;\n    expect(cw.pr_url).toBe('https://github.com/example/repo/pull/2');\n    expect(cw.verification).toEqual(verification);\n  });\n\n  it('上下文有合同对抗摘要 gan 与升级 escalations → 一并写入 result.coding_workflow（coding commander 据此处理）', async () => {\n    const gan = { verdict: 'FORCED', rounds: 3, trend: 'oscillating', open_issues: [{ id: 'R-1', severity: '阻断', targets: ['S-1'] }], cost_usd: 2 };\n    const escalations = [{ type: 'gan_forced', trend: 'oscillating', round: 3, open_issues: gan.open_issues }];\n    const r = await runActivityProcess(ENTRY, input({ gan, escalations }));\n    expect(r.exitCode, r.stderr).toBe(0);\n    const cw = JSON.parse(requests[0].raw).result.coding_workflow;\n    expect(cw.gan).toEqual(gan);\n    expect(cw.escalations).toEqual(escalations);\n  });\n  it('没有 pr_url 但有 verification -> 仍 PATCH 失败结论，回写成功即 completed', async () => {\n    const r = await runActivityProcess(ENTRY, input({ pr_url: undefined, branch: undefined, chain_files: undefined, verification }));\n    expect(r.exitCode, r.stderr).toBe(0);\n    expect(r.result.status).toBe('completed');\n    expect(r.result.outputs).toEqual({ reported: true });\n    expect(requests).toHaveLength(1);\n    const body = JSON.parse(requests[0].raw);\n    expect(Object.keys(body)).toEqual(['result']);\n    expect(body.result.coding_workflow).toEqual({ status: 'failed', run_tag: 'rt-1', sprint_dir: 'sprints/s1', verification, ...unknownHandoff });\n  });\n\n  it('没有 pr_url、verification 不是对象 -> 维持 fatal pr_url_missing，请求数 0', async () => {\n    const r = await runActivityProcess(ENTRY, input({ pr_url: undefined, verification: 'failed' }));\n    expect(r.result.reason_code).toBe('pr_url_missing');\n    expect(requests).toHaveLength(0);\n  });\n\n  it('没有 pr_url 的失败回写遇 Brain 500 -> retryable brain_unavailable', async () => {\n    reply = { status: 500, body: {} };\n    const r = await runActivityProcess(ENTRY, input({ pr_url: undefined, verification }));\n    expect(r.result.failure_class).toBe('retryable');\n    expect(r.result.reason_code).toBe('brain_unavailable');\n  });\n\n  it('缺 task_id -> fatal task_id_missing，请求数 0', async () => {\n    const r = await runActivityProcess(ENTRY, input({ task_id: '' }));\n    expect(r.exitCode).toBe(2);\n    expect(r.result.failure_class).toBe('fatal');\n    expect(r.result.reason_code).toBe('task_id_missing');\n    expect(requests).toHaveLength(0);\n  });\n\n  it('不碰文件系统：不要求 worktree，sprint_dir 原样回写', async () => {\n    const r = await runActivityProcess(ENTRY, input({ sprint_dir: 'sprints/weird' }));\n    expect(r.exitCode).toBe(0);\n    expect(JSON.parse(requests[0].raw).result.coding_workflow.sprint_dir).toBe('sprints/weird');\n  });\n});\n",
  "packages/brain/scripts/coding-workflow/__tests__/fixtures/fake-claude.mjs": "#!/usr/bin/env node\n// 假 claude：按 FAKE_CLAUDE_MODE 模拟 `claude -p <prompt> ...`。\n// spec 用：ok | nofile | auth | fail | outside | sleep | linger | titled | noids | uncovered | noqa | qa-unsupported；\n// build 用：build-ok（真实 git commit 并写 03-build.md）| build-nocommit | build-dirty（另留未提交改动）| build-noreport\n// | build-amend（把改动 amend 进运行前的 HEAD）| build-badreport（03 的 upstream 只覆盖第一条 S-n）；\n// verify 用：verify-pass | verify-fail（最后一条 FAIL）| verify-badformat（第一条缺 output）| verify-uncovered（只覆盖第一条 I-n）\n// | verify-outside（全 PASS 但往 worktree 根写越界文件）| verify-reset（先 git reset --hard HEAD~1 再写全 PASS 的 04）\n// | verify-fabricated（04 写了命令与输出，但对话记录里没执行过）| verify-bizauth（业务输出含 authentication failed 后非 0 退出）\n// | verify-authresult（result 事件报鉴权错误后非 0 退出）| verify-cdprefix（全 PASS，证据命令带 cd <worktree> && 前缀）。verify-* 会在 stdout 输出 stream-json 的 tool_use/tool_result。\n// spec_review 评审用（写 REVIEW_PATH）：review-approve | review-revise（始终 REVISE + R-1 针对 S-1）\n// | review-until-fixed（02 含「已按评审修改」时 APPROVE，否则同 review-revise）| review-badformat（无 verdict 行）\n// | review-outside（同 review-approve，另往 worktree 根写越界文件）；\n// spec_review 改写用：revise-ok（保留 02 的 frontmatter 与全部 S-n，末尾 S-n 正文追加「已按评审修改 R-1」）| revise-delete（删掉 02）。\n// prompt 含 `ROLE: spec_review` / `ROLE: spec_revise` 时输出 `FAKE_ROLE: <角色>` 一行供计数，\n// FAKE_CLAUDE_MODE_REVIEW / FAKE_CLAUDE_MODE_REVISE 可单独指定该步模式。\n// FAKE_CLAUDE_PID_FILE 指向文件时，启动即把自己的 pid 写进去（测试据此确认进程已被清理）。\n// FAKE_CLAUDE_CHILD_PID_FILE 指向文件时，sleep / linger 模式额外起一个长睡孙进程并写入其 pid；\n// FAKE_CLAUDE_CHILD_STDIO=ignore 时孙进程不继承输出管道，否则继承（握着管道）。\n// linger：照常写出合法 02-spec.md 并退出 0，但留下孙进程。\n// 越轨副作用（模拟工具闸失守，任一模式写完产物后执行）：FAKE_TAMPER_FILE 追加改写该文件；\n// FAKE_SWITCH_BRANCH 切到新分支；FAKE_PUSH=1 把当前分支推到 origin；FAKE_DELETE_FILE 删除该文件。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { spawn, execFileSync } from 'node:child_process';\n\nconst argv = process.argv.slice(2);\nconst prompt = argv[argv.indexOf('-p') + 1] || '';\n// 按 prompt 认出 build / verify 步骤：FAKE_CLAUDE_MODE_BUILD / FAKE_CLAUDE_MODE_VERIFY 可单独指定该步模式（端到端一次跑三步用）\n// spec_review 的评审/改写会话按 ROLE 行认出：FAKE_CLAUDE_MODE_REVIEW / FAKE_CLAUDE_MODE_REVISE\n// build 内 CI 门禁预检修复会话按 `ROLE: ci_precheck_fix` 认出：FAKE_CLAUDE_MODE_PRECHECK\n//   precheck-fix（提交 src/precheck-fixed.txt）| precheck-noop（什么都不改）| precheck-sprint（改 02 并提交，越界）\nconst role = (prompt.match(/^ROLE: (spec_review|spec_revise|ci_precheck_fix)$/m) || [])[1];\nconst ROLE_STEPS = { spec_review: 'REVIEW', spec_revise: 'REVISE', ci_precheck_fix: 'PRECHECK' };\nif (process.env.FAKE_PROMPT_LOG && role === 'ci_precheck_fix') fs.appendFileSync(process.env.FAKE_PROMPT_LOG, `${prompt}\\n`);\nconst step = role ? ROLE_STEPS[role]\n  : /^BUILD_PATH: /m.test(prompt) ? 'BUILD' : /^EVIDENCE_PATH: /m.test(prompt) ? 'VERIFY' : null;\nconst mode = (step && process.env[`FAKE_CLAUDE_MODE_${step}`]) || process.env.FAKE_CLAUDE_MODE || 'ok';\n\nif (process.env.FAKE_CLAUDE_PID_FILE) fs.writeFileSync(process.env.FAKE_CLAUDE_PID_FILE, String(process.pid));\n\n// 孙进程：与真 claude 起的子工具进程一样（默认继承 stdio，握着父进程的输出管道）；60s 后自行退出，防测试泄漏\nfunction spawnGrandchild() {\n  if (!process.env.FAKE_CLAUDE_CHILD_PID_FILE) return;\n  const stdio = process.env.FAKE_CLAUDE_CHILD_STDIO === 'ignore' ? 'ignore' : 'inherit';\n  const grandchild = spawn(process.execPath, ['-e', 'setTimeout(() => {}, 60000)'], { stdio });\n  grandchild.unref(); // 孙进程不拖住假 claude 自身退出（linger 模式需要 claude 先退、孙进程留下）\n  fs.writeFileSync(process.env.FAKE_CLAUDE_CHILD_PID_FILE, String(grandchild.pid));\n}\n\n// sleep：长睡且不写任何文件，模拟 claude 卡死（默认 SIGTERM 即可终止）\nif (mode === 'sleep') {\n  spawnGrandchild();\n  setInterval(() => {}, 1000);\n  await new Promise(() => {});\n}\n\nif (mode === 'auth') {\n  process.stderr.write('Invalid API key · Please run /login\\n');\n  process.exit(1);\n}\nif (mode === 'fail') {\n  process.stderr.write(`${process.env.FAKE_CLAUDE_TEXT || 'something went wrong'}\\n`);\n  process.exit(1);\n}\n\n// FAKE_CLAUDE_MARKER：stdout 与 stderr 各输出一行带标记的文字（会话输出去向测试用）\nif (process.env.FAKE_CLAUDE_MARKER) {\n  console.log(`STDOUT ${process.env.FAKE_CLAUDE_MARKER}`);\n  process.stderr.write(`STDERR ${process.env.FAKE_CLAUDE_MARKER}\\n`);\n}\nconst unset = (k) => process.env[k] ?? '<unset>';\nif (role) console.log(`FAKE_ROLE: ${role}`);\nconsole.log(`FAKE_ARGS: ${argv.filter((a) => a !== prompt).join(' ')}`);\nconsole.log(`FAKE_CWD: ${process.cwd()}`);\nconsole.log(`FAKE_ENV: CLAUDECODE=${unset('CLAUDECODE')} CLAUDE_CODE_ENTRYPOINT=${unset('CLAUDE_CODE_ENTRYPOINT')} GIT_DIR=${unset('GIT_DIR')}`);\nconsole.log(`FAKE_CODING_WF_KEYS: ${Object.keys(process.env).filter((k) => k.startsWith('CODING_WF_')).sort().join(',') || 'none'}`);\nconsole.log(`FAKE_GH_ENV:GH_TOKEN=${unset('GH_TOKEN')} GITHUB_TOKEN=${unset('GITHUB_TOKEN')} GH_ENTERPRISE_TOKEN=${unset('GH_ENTERPRISE_TOKEN')} GIT_TERMINAL_PROMPT=${unset('GIT_TERMINAL_PROMPT')}`);\nconsole.log(`FAKE_GH_CONFIG_DIR: ${unset('GH_CONFIG_DIR')}`);\nconsole.log(`FAKE_GH_CONFIG_EMPTY: ${Boolean(process.env.GH_CONFIG_DIR) && fs.existsSync(process.env.GH_CONFIG_DIR) && fs.readdirSync(process.env.GH_CONFIG_DIR).length === 0}`);\nconsole.log(`FAKE_INTENT_PATH: ${(prompt.match(/^INTENT_PATH: (.+)$/m) || [])[1]}`);\nconsole.log(`FAKE_PREV_ERRORS: ${(prompt.match(/^PREV_ERRORS: (.*)$/m) || [])[1]}`);\nconsole.log(`FAKE_PROMPT_MENTIONS_BUILD: ${prompt.includes('03-build')}`);\nfor (let i = 0; i < 200; i += 1) console.log(`fake claude log line ${i}`);\n\nif (mode === 'nofile') process.exit(0);\n\nconst field = (name) => (prompt.match(new RegExp(`^${name}: (.+)$`, 'm')) || [])[1];\nconst idList = (name) => (field(name) || '').split(',').map((s) => s.trim()).filter(Boolean);\nconst taskId = field('TASK_ID');\nconst frontmatter = (step, upstream) => `---\\ntask_id: ${taskId}\\nstep: ${step}\\nupstream: ${JSON.stringify(upstream)}\\n---\\n`;\nconst writeFile = (file, text) => {\n  fs.mkdirSync(path.dirname(file), { recursive: true });\n  fs.writeFileSync(file, text);\n};\nconst git = (...args) => execFileSync('git', args, { encoding: 'utf8' });\n\n// build-*：在当前分支真实提交一份代码+测试，再按 SPEC_IDS 写 03-build.md\nfunction build() {\n  // 捕获真实活动传给 CLI 的输入，读取实际 intent；仅测试显式开启，不模拟模型语义判断。\n  if (process.env.FAKE_BUILD_CONTEXT_FILE) {\n    const intentPath = field('INTENT_PATH');\n    fs.writeFileSync(process.env.FAKE_BUILD_CONTEXT_FILE, JSON.stringify({\n      intent_path: intentPath, intent: fs.readFileSync(intentPath, 'utf8'),\n      spec_path: field('SPEC_PATH'), prompt,\n    }));\n  }\n  let sha = '';\n  if (mode === 'build-amend') {\n    writeFile('src/feature.js', 'export const feature = () => 0;\\n');\n    git('add', '--', 'src');\n    git('commit', '-q', '--amend', '-m', 'feat: amended');\n    sha = git('rev-parse', 'HEAD').trim();\n  } else if (mode !== 'build-nocommit') {\n    // FAKE_BUILD_COMMITS：连续提交几次（默认 1）；FAKE_BUILD_EXTRA_FILE：额外一并提交的文件（相对 worktree）\n    for (let i = 1; i <= Number(process.env.FAKE_BUILD_COMMITS || 1); i += 1) {\n      writeFile('src/feature.js', `export const feature = () => ${i};\\n`);\n      writeFile('src/feature.test.js', `import { feature } from './feature.js'; // ${i}\\n`);\n      git('add', '--', 'src');\n      if (process.env.FAKE_BUILD_EXTRA_FILE) {\n        writeFile(process.env.FAKE_BUILD_EXTRA_FILE, `extra ${i}\\n`);\n        git('add', '--', process.env.FAKE_BUILD_EXTRA_FILE);\n      }\n      git('commit', '-q', '-m', `feat: build feature ${i}`);\n    }\n    sha = git('rev-parse', 'HEAD').trim();\n  }\n  if (mode === 'build-dirty') writeFile('src/dirty.js', 'uncommitted\\n');\n  if (mode === 'build-noreport') return;\n  const ids = idList('SPEC_IDS');\n  const upstream = (mode === 'build-badreport' ? ids.slice(0, 1) : ids).map((id) => `02-spec.md#${id}`);\n  const sections = ids.map((id, i) => `### B-${i + 1}\\n对应 ${id}；改动 src/feature.js；测试 src/feature.test.js；命令 npm test；提交 ${sha}\\n`);\n  writeFile(field('BUILD_PATH'), `${frontmatter('build', upstream)}# build\\n\\n${sections.join('\\n')}`);\n  if (process.env.FAKE_MATERIAL_RECORD) {\n    const record = JSON.parse(fs.readFileSync(process.env.FAKE_MATERIAL_RECORD, 'utf8'));\n    record.candidate_sha = git('rev-parse', 'HEAD').trim();\n    fs.appendFileSync(field('BUILD_PATH'), '\\n## 材料同步记录\\n```json\\n' + JSON.stringify(record) + '\\n```\\n');\n  }\n\n}\n\n// 模拟 stream-json 对话记录里的一次 Bash 执行（tool_use + tool_result）\nlet toolSeq = 0;\nfunction emitBash(command, result) {\n  toolSeq += 1;\n  const id = `toolu_${toolSeq}`;\n  console.log(JSON.stringify({ type: 'assistant', message: { content: [{ type: 'tool_use', id, name: 'Bash', input: { command } }] } }));\n  console.log(JSON.stringify({ type: 'user', message: { content: [{ type: 'tool_result', tool_use_id: id, content: result }] } }));\n}\n\n// verify-*：按 INTENT_IDS 写 04-evidence.md，并为每条证据输出对应的执行记录（verify-fabricated 不输出）\nfunction verify() {\n  // verify-bizauth：业务命令输出里有 authentication failed，claude 以非鉴权原因非 0 退出\n  if (mode === 'verify-bizauth') {\n    emitBash('npm test', 'FAIL auth.test.js > login: authentication failed for user admin');\n    console.log(JSON.stringify({ type: 'result', subtype: 'error_max_turns', is_error: true, result: 'max turns reached' }));\n    process.exit(1);\n  }\n  // verify-authresult：claude 自身的 result 事件报鉴权错误\n  if (mode === 'verify-authresult') {\n    console.log(JSON.stringify({ type: 'result', subtype: 'error', is_error: true, result: 'Invalid API key · Please run /login' }));\n    process.exit(1);\n  }\n  console.log(`FAKE_BUILD_PRESENT: ${fs.existsSync(path.join(path.dirname(field('EVIDENCE_PATH')), '03-build.md'))}`);\n  if (mode === 'verify-reset') git('reset', '-q', '--hard', 'HEAD~1');\n  const ids = idList('INTENT_IDS');\n  const covered = mode === 'verify-uncovered' ? ids.slice(0, 1) : ids;\n  const fence = '```';\n  const sections = covered.map((id, i) => {\n    const failed = mode === 'verify-fail' && i === covered.length - 1;\n    const command = `npm test -- ${id}`;\n    const output = failed ? 'AssertionError: expected 500 to be 200' : `ok ${id} passed`;\n    if (mode !== 'verify-fabricated') emitBash(command, `> vitest run ${id}\\n${output}\\n`);\n    // verify-cdprefix：会话已在 worktree 里执行，写证据时补上 cd <当前目录> && 前缀（真实 claude 实测行为）\n    const written = mode === 'verify-cdprefix' ? `cd ${process.cwd()} && ${command}` : command;\n    const lines = [`### E-${i + 1}`, `对应: ${id}`, `verdict: ${failed ? 'FAIL' : 'PASS'}`, `${fence}command`, written, fence];\n    if (!(mode === 'verify-badformat' && i === 0)) lines.push(`${fence}output`, output, fence);\n    return `${lines.join('\\n')}\\n`;\n  });\n  writeFile(field('EVIDENCE_PATH'), `${frontmatter('verify', ids.map((id) => `01-intent.md#${id}`))}# 验收证据\\n\\n${sections.join('\\n')}`);\n  if (mode === 'verify-outside') fs.writeFileSync('stray.txt', 'out of scope\\n');\n}\n\nconst FIXED_MARK = '已按评审修改';\n\n// review-*：按 SPEC_IDS 写 02-review.md\nfunction review() {\n  const specText = fs.readFileSync(field('SPEC_PATH'), 'utf8');\n  const approve = mode === 'review-approve' || mode === 'review-outside'\n    || (mode === 'review-until-fixed' && specText.includes(FIXED_MARK));\n  const upstream = idList('SPEC_IDS').map((id) => `02-spec.md#${id}`);\n  // 合同对抗 v2 格式：## 评分（5 维）+ 阻断问题需带场景与依据；结论由程序判\n  const scores = (v) => `## 评分\\n意图对齐: ${v}\\n可验证: ${v}\\n场景覆盖: ${v}\\n回归风险: ${v}\\n可执行: ${v}\\n`;\n  const body = mode === 'review-badformat'\n    ? '# 评审\\n\\n看起来还行。\\n'\n    : approve\n      ? `# 评审\\n\\n${scores(8)}`\n      : `# 评审\\n\\n${scores(5)}\\n### R-1\\n针对: S-1\\n严重度: 阻断\\n场景: QA 按 S-1 验收时没有可运行的命令，无法判断是否达成\\n依据: S-1 只写了\"测试通过\"\\nS-1 需给出具体命令。\\n`;\n  writeFile(field('REVIEW_PATH'), `${frontmatter('spec_review', upstream)}${body}`);\n  if (mode === 'review-outside') fs.writeFileSync('stray.txt', 'out of scope\\n');\n}\n\n// revise-ok：02 末尾（最后一条 S-n 正文）追加一行改写标记，frontmatter 与 S-n 不动\nfunction revise() {\n  const specPath = field('SPEC_PATH');\n  if (mode === 'revise-delete') {\n    fs.rmSync(specPath, { force: true });\n    return;\n  }\n  const text = fs.readFileSync(specPath, 'utf8');\n  fs.writeFileSync(specPath, `${text.replace(/\\n*$/, '\\n')}${FIXED_MARK} R-1\\n`);\n}\n\nfunction sideEffects() {\n  if (process.env.FAKE_DELETE_FILE) fs.rmSync(process.env.FAKE_DELETE_FILE, { force: true });\n  if (process.env.FAKE_TAMPER_FILE) fs.appendFileSync(process.env.FAKE_TAMPER_FILE, '\\n篡改\\n');\n  if (process.env.FAKE_SWITCH_BRANCH) git('checkout', '-q', '-b', process.env.FAKE_SWITCH_BRANCH);\n  if (process.env.FAKE_PUSH === '1') git('push', '-q', 'origin', `HEAD:refs/heads/${git('rev-parse', '--abbrev-ref', 'HEAD').trim()}`);\n}\n\nfunction precheckFix() {\n  if (mode === 'precheck-fix') {\n    writeFile('src/precheck-fixed.txt', 'fixed\\n');\n    git('add', '--', 'src/precheck-fixed.txt');\n    git('commit', '-q', '-m', 'fix: CI 门禁预检');\n    if (process.env.FAKE_MATERIAL_RECORD && process.env.FAKE_KEEP_STALE_MATERIAL_RECORD !== '1' && prompt.includes('仅允许更新 03-build.md')) {\n      const file = field('BUILD_PATH');\n      const text = fs.readFileSync(file, 'utf8');\n      const [prefix, json] = text.split('## 材料同步记录\\n```json\\n');\n      const record = JSON.parse(json.split('\\n```')[0]);\n      record.candidate_sha = git('rev-parse', 'HEAD').trim();\n      const output = git('show', '--stat', '--oneline', 'HEAD');\n      record.materials = record.materials.map((row) => ({ ...row, command: 'git show --stat --oneline HEAD', output }));\n      fs.writeFileSync(file, prefix + '## 材料同步记录\\n```json\\n' + JSON.stringify(record) + '\\n```\\n');\n    }\n\n  }\n  if (mode === 'precheck-sprint') {\n    const spec = path.join(field('SPRINT_DIR'), '02-spec.md');\n    fs.appendFileSync(spec, '\\n改了合同\\n');\n    git('add', '--', spec);\n    git('commit', '-q', '-m', 'fix: 改合同');\n  }\n}\n\nif (mode.startsWith('precheck-')) precheckFix();\nelse if (mode.startsWith('build-')) build();\nelse if (mode.startsWith('verify-')) verify();\nelse if (mode.startsWith('review-')) review();\nelse if (mode.startsWith('revise-')) revise();\nelse {\n  const ids = idList('INTENT_IDS');\n  // titled：标题行带说明文字（真实 claude 实测 c2afa8ba）；noids：没有 S-n 标题；uncovered：upstream 只覆盖第一条 I-n\n  const heading = (i) => (mode === 'titled' ? `### S-${i + 1} 改 foo.js 的第 ${i + 1} 处` : mode === 'noids' ? `#### 规格 ${i + 1}` : `### S-${i + 1}`);\n  const sections = ids.map((id, i) => `${heading(i)}\\n对应 ${id}：改 foo.js，验证 npm test\\n`);\n  // QA 场景：每个 I-n 一条（noqa 模式不写，模拟漏写）\n  // 审计 #10：02 必须登记未覆盖的真实链路（可写「无：理由」）\n  if (mode !== 'nouncovered') sections.push('## 未覆盖真实链路\\n\\n无：测试替身，没有外部调用方');\n  // qa-unsupported：本仓 QA 模式（local）验不了的任务（UI / 真机），spec 写 QA_UNSUPPORTED 上交（C6）\n  if (mode === 'qa-unsupported') sections.push('QA_UNSUPPORTED: 需要真机点按抖音发布页，local 黑盒验不了\\n');\n  console.error(`FAKE_REPO_RULES: ${/本仓库规矩（([^）]+)）/.exec(prompt)?.[1] ?? '无'}`);\n  if (mode !== 'noqa') sections.push(`## QA 场景\\n\\n${ids.map((id, i) => `### Q-${i + 1}\\n对应: ${id}\\n操作: 用户按 ${id} 操作\\n期望: 看到 ${id} 的结果\\n`).join('\\n')}`);\n  // 铁律对照：prompt 给了 INVARIANTS_PATH 且清单里有 INV-n 时逐条写不适用（noinv 模式不写，模拟漏写）\n  const invPath = field('INVARIANTS_PATH');\n  const invIds = invPath && fs.existsSync(invPath) ? [...fs.readFileSync(invPath, 'utf8').matchAll(/^### (INV-[0-9a-f]{8})/gm)].map((m) => m[1]) : [];\n  if (invIds.length > 0 && mode !== 'noinv') {\n    sections.push(`## 铁律对照\\n\\n${invIds.map((id) => `- ${id}：不适用：这条约束的是别的业务线，本改动不涉及`).join('\\n')}\\n`);\n  }\n  const upstream = (mode === 'uncovered' ? ids.slice(0, 1) : ids).map((id) => `01-intent.md#${id}`);\n  writeFile(field('SPEC_PATH'), `${frontmatter('spec', upstream)}# spec\\n\\n${sections.join('\\n')}`);\n  // outside：除合法 02-spec.md 外，再往 worktree 根（子进程 cwd）写一个越界文件\n  if (mode === 'outside') fs.writeFileSync('stray.txt', 'out of scope\\n');\n  if (mode === 'linger') spawnGrandchild();\n}\nsideEffects();\n// FAKE_CLAUDE_COST：末尾输出一行 result 事件（真 claude --output-format json 的形状），供计费测试\nif (process.env.FAKE_CLAUDE_COST) console.log(JSON.stringify({ type: 'result', subtype: 'success', is_error: false, total_cost_usd: Number(process.env.FAKE_CLAUDE_COST) }));\n",
  "packages/brain/scripts/coding-workflow/__tests__/helpers/material-fixture.mjs": "import fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\nimport { initCommittableRepo, git } from './git.mjs';\nimport { renderIntent } from '../../lib/intent.mjs';\nexport const hash = (value) => crypto.createHash('sha256').update(value).digest('hex');\nexport const fm = (task, step, upstream) => `---\\ntask_id: ${task}\\nstep: ${step}\\nupstream: ${JSON.stringify(upstream)}\\n---\\n`;\nexport function materialFixture() {\n  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cw-material-chain-'));\n  initCommittableRepo(root, path.join(root, '.hooks'));\n  const task = 'material-task-1';\n  const sources = { spec: ['spec.md','规格'], rule:['rule.md','<!-- rule: preserve -->\\n保留旧行为。'], sample:['sample.json','{\"ok\":true}'], implementation:['code.mjs','old'] };\n  const refs=Object.entries(sources).map(([kind,[file,content]])=>{\n    fs.writeFileSync(path.join(root,file),content);\n    return {ref_id:kind,kind,path:file,required:true};\n  });\n  fs.mkdirSync(path.join(root,'docs/registry'),{recursive:true});\n  fs.writeFileSync(path.join(root,'docs/registry/coding-workflow-authority.json'),JSON.stringify({object_id:'coding-workflow',refs}));\n  git(root,'add','.');git(root,'commit','-qm','baseline');\n  const base=git(root,'rev-parse','HEAD').trim();git(root,'update-ref','refs/remotes/origin/main',base);\n  const authority={object_id:'coding-workflow',refs:refs.map(r=>({...r,revision:base,digest:hash(fs.readFileSync(path.join(root,r.path)))}))};\n  const facts=authority.refs.map(r=>({...r,object_id:authority.object_id,actual_digest:r.digest,status:'found',reason:null}));\n  const dir=path.join(root,'sprints/s1');fs.mkdirSync(dir,{recursive:true});\n  const intent=renderIntent({taskId:task,title:'材料同步',items:['更新实现且保留原规格规则样本。'],authorityFacts:facts});\n  fs.writeFileSync(path.join(dir,'01-intent.md'),intent);\n  const links={reason:'本次边界',intent_ids:['I-1'],spec_ids:['S-1'],qa_ids:['Q-1'],approval_refs:[]};\n  const plan={version:1,rules:[{ref_id:'rule',rule_id:'preserve',action:'keep',...links}],materials:refs.map(r=>({...r,action:r.kind==='implementation'?'update':'keep',...links,verification:'真实文件差异'}))};\n  const spec=fm(task,'spec',['01-intent.md#I-1'])+'### S-1\\n更新实现。\\n### Q-1\\n对应: I-1\\n前提: 固定基线\\n操作: 检查\\n期望: 正确\\n## 未覆盖真实链路\\n无：本地Git范围\\n## 旧规则与材料计划\\n```json\\n'+JSON.stringify(plan)+'\\n```\\n';\n  fs.writeFileSync(path.join(dir,'02-spec.md'),spec);\n  fs.writeFileSync(path.join(root,'code.mjs'),'new');git(root,'add','code.mjs');git(root,'commit','-qm','candidate');\n  const candidate=git(root,'rev-parse','HEAD').trim();\n  const record={version:1,task_id:task,run_tag:'run-1',base_sha:base,candidate_sha:candidate,spec_sha256:hash(spec),materials:plan.materials.map(r=>({ref_id:r.ref_id,path:r.path,action:r.action,verification:r.verification,command:'git diff --stat',output:'code.mjs changed'}))};\n  const writeRecord=()=>fs.writeFileSync(path.join(dir,'03-build.md'),fm(task,'build',['02-spec.md#S-1'])+'### B-1\\n实现\\n## 材料同步记录\\n```json\\n'+JSON.stringify(record)+'\\n```\\n');\n  writeRecord();\n  fs.writeFileSync(path.join(dir,'04-evidence.md'),fm(task,'verify',['01-intent.md#I-1'])+'### E-1\\nfixture chain\\n');\n  const input={task_id:task,run_tag:'run-1',worktree:root,sprint_dir:'sprints/s1',authority_required:true,authority,trusted_repo:root,authority_index_sha:base,initial_base_sha:base,\n    intent_ids:['I-1'],intent_sha256:hash(intent),spec_sha256:hash(spec),candidate_sha:candidate,build_sha256:hash(fs.readFileSync(path.join(dir,'03-build.md'))),intent_file:'01-intent.md',spec_file:'02-spec.md',build_file:'03-build.md',evidence_file:'04-evidence.md'};\n  return {root,dir,base,candidate,input,plan,record,writeRecord,cleanup:()=>fs.rmSync(root,{recursive:true,force:true})};\n}\n",
  "packages/brain/scripts/coding-workflow/activities/build.mjs": "import { sumCostUsd } from '../lib/transcript.mjs';\n// build 活动：用 claude CLI 按 02-spec.md 的每条 S-n 以 TDD 写代码并在当前分支提交，写 <sprint_dir>/03-build.md。\n// 程序做后置检查：远端未变、历史未改写、md 链未被改/未被提交、03 合规、HEAD 前进、无新的未提交改动、未碰 agent 配置；\n// 再跑 CI 门禁本地预检（lib/ci-precheck.mjs），红了起修复会话至多 2 轮，每轮修完重新过全部后置检查。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { runActivity, validateBase, fail } from '../lib/protocol.mjs';\nimport { parseFrontmatter, extractAnchors, reportErrors } from '../lib/md-chain.mjs';\nimport {\n  loadPrompt, claudeTimeoutMs, runClaude, claudeFailure, gitOut, headSha, snapshotChanges, outOfScopeChanges, sprintChangesExcept,\n} from '../lib/claude.mjs';\nimport {\n  chainTamperFailure, remoteChangeFailure, remoteSnapshot, currentBranch, isAncestor, changedFilesSince, agentConfigFiles, sha256File,\n} from '../lib/guards.mjs';\nimport { checksFor, runPrechecks } from '../lib/ci-precheck.mjs';\nimport { repoRules } from '../lib/repo-profile.mjs';\nimport { intentHeading, prKindOf } from '../lib/pr-kind.mjs';\nimport { INTENT_FILE } from '../lib/spec-check.mjs';\n\nconst spend = { usd: 0 };\n\nconst SPEC_FILE = '02-spec.md';\nconst BUILD_FILE = '03-build.md';\nconst SPEC_ID_RE = /^S-\\d+$/;\n// 默认 = budget 2400s - 90s：超时由本活动先报 claude_timeout，并给 claude 退出后的检查阶段（含 ls-remote）留余量\nconst TIMEOUT = { envVar: 'CODING_WF_BUILD_TIMEOUT_MS', defaultMs: 2310000, reserveMs: 75000 };\n// 允许 Bash 跑测试；deny 优先于 allow，推送与开 PR 留给 publish\nconst CLAUDE_TOOLS = ['--allowedTools', 'Bash', '--disallowedTools', 'Bash(git push:*)', 'Bash(gh:*)'];\nconst PRECHECK_FIX_ROUNDS = 2;\nconst PRECHECK_FIX_TIMEOUT_MS = 10 * 60 * 1000;\nconst posInt = (v, d) => (/^[1-9][0-9]*$/.test(v ?? '') ? Number(v) : d);\n\n/** 02-spec.md 里的全部 S-n；文件不存在返回 null。 */\nfunction specIds(specPath) {\n  if (!fs.existsSync(specPath)) return null;\n  const text = fs.readFileSync(specPath, 'utf8');\n  return extractAnchors(parseFrontmatter(text)?.body ?? text).filter((id) => SPEC_ID_RE.test(id));\n}\n\n/** git 查询本身失败：不能当成\"没问题\"，交给重试。 */\nconst gitCheckFailed = (check) => fail('retryable', 'git_check_failed', { evidence: [{ check }] });\n\n/** 运行后检查：远端、历史/分支、md 链。有问题返回 fail，否则 null。 */\nasync function guardFailure({ worktree, dir, sprintDir, input, before }) {\n  const remote = await remoteChangeFailure(worktree, before.remote);\n  if (remote) return remote;\n  const headAfter = await headSha(worktree);\n  const branchAfter = await currentBranch(worktree);\n  const ancestor = await isAncestor(worktree, before.head);\n  if (ancestor === null) return gitCheckFailed('merge-base --is-ancestor');\n  if (branchAfter !== before.branch || !ancestor) {\n    const evidence = { head_before: before.head, head_after: headAfter, branch_before: before.branch, branch_after: branchAfter };\n    return fail('fatal', 'build_history_rewritten', { evidence: [evidence] });\n  }\n  const tampered = chainTamperFailure(dir, input);\n  if (tampered) return tampered;\n  const committed = await changedFilesSince(worktree, before.head, sprintDir);\n  if (committed === null) return gitCheckFailed('diff --name-only');\n  if (committed.length > 0) return fail('fatal', 'chain_tampered', { evidence: [{ committed_sprint_files: committed }] });\n  return null;\n}\n\n/** 会话结束后的工作区检查：无未提交改动、sprint 目录只动 03、不碰 agent 配置。有问题返回 fail，否则 null。 */\nasync function postFailure({ worktree, sprintDir, before }) {\n  const uncommitted = await outOfScopeChanges(worktree, sprintDir, before.changes, 'build');\n  if (uncommitted.length > 0) return fail('fatal', 'build_uncommitted', { evidence: [{ uncommitted_changes: uncommitted }] });\n  // sprint 目录只允许新增/修改 03（CLAUDE.md、.claude/ 等放进 sprint 目录同样会影响后续会话）\n  const polluted = await sprintChangesExcept(worktree, sprintDir, before.changes, BUILD_FILE, 'build');\n  if (polluted.length > 0) return fail('fatal', 'build_sprint_polluted', { evidence: [{ files: polluted }] });\n  const changed = await changedFilesSince(worktree, before.head);\n  if (changed === null) return gitCheckFailed('diff --name-only');\n  if (changed.includes('.implementation-source-relations.json')) return fail('fatal', 'build_touched_controlled_metadata', { evidence: [{ files: ['.implementation-source-relations.json'] }] });\n  const agentFiles = agentConfigFiles(changed);\n  if (agentFiles.length > 0) return fail('fatal', 'build_touched_agent_config', { evidence: [{ files: agentFiles }] });\n  return null;\n}\n\nconst failedNames = (results) => results.filter((r) => !r.ok).map((r) => r.name);\n\n/**\n * CI 门禁本地预检（审计 P1 #4）：跑门禁 → 有红则起修复会话（至多 PRECHECK_FIX_ROUNDS 轮，每轮修完重新过全部后置检查）→ 重跑。\n * 修复会话越界（改合同/历史/agent 配置等）→ { failure }；修不好或会话失败 → 不卡链路，summary 标明未过的门禁交给 CI 与 CI 修复环。\n */\nasync function precheckLoop({ worktree, dir, sprintDir, input, before }) {\n  const feature = prKindOf(intentHeading(dir)) === 'feat';\n  // 预检清单按仓库（repos.json prechecks，C6）\n  const checks = process.env.CODING_WF_PRECHECKS ? JSON.parse(process.env.CODING_WF_PRECHECKS) : checksFor(input.repo_profile, { branch: before.branch, feature });\n  const env = { PR_LABELS: feature ? 'feature' : '' };\n  let results = await runPrechecks(worktree, { checks, env });\n  let rounds = 0;\n  while (failedNames(results).length > 0 && rounds < PRECHECK_FIX_ROUNDS) {\n    rounds += 1;\n    const failures = results.filter((r) => !r.ok).map((r) => `### ${r.name}\\n\\`\\`\\`\\n${r.output_tail}\\n\\`\\`\\``).join('\\n\\n');\n    const prompt = loadPrompt('ci-precheck-fix', {\n      BRANCH: before.branch, SPRINT_DIR: dir, BUILD_PATH: path.join(dir, BUILD_FILE), INTENT_PATH: path.join(dir, '01-intent.md'), SPEC_PATH: path.join(dir, SPEC_FILE), FAILURES: failures,\n      REPO_RULES: repoRules(input.repo_profile),\n    });\n    const timeoutMs = posInt(process.env.CODING_WF_PRECHECK_FIX_TIMEOUT_MS, PRECHECK_FIX_TIMEOUT_MS);\n    const run = await runClaude({ args: ['-p', prompt, '--permission-mode', 'acceptEdits', ...CLAUDE_TOOLS], cwd: worktree, timeoutMs, tag: 'ci-precheck-fix', isolateRemote: true });\n    spend.usd = sumCostUsd(spend.usd, run.cost_usd);\n    const violation = (await guardFailure({ worktree, dir, sprintDir, input, before })) ?? (await postFailure({ worktree, sprintDir, before }));\n    if (violation) return { failure: violation };\n    if (claudeFailure(run)) break;\n    results = await runPrechecks(worktree, { checks, env });\n  }\n  const failures = failedNames(results);\n  return { summary: { passed: failures.length === 0, rounds, failures } };\n}\n\nasync function main(input) {\n  const { worktree, sprint_dir: sprintDir } = input;\n  const { dir } = validateBase(input);\n\n  const specPath = path.join(dir, SPEC_FILE);\n  const ids = specIds(specPath);\n  if (ids === null) return fail('fatal', 'spec_missing');\n  if (ids.length === 0) return fail('fatal', 'spec_ids_missing');\n  const headBefore = await headSha(worktree);\n  if (!headBefore) return fail('fatal', 'git_head_unavailable');\n\n  const buildPath = path.join(dir, BUILD_FILE);\n  const prompt = loadPrompt('build', {\n    TASK_ID: input.task_id,\n    RUN_TAG: input.run_tag ?? '',\n    INITIAL_BASE_SHA: input.initial_base_sha ?? 'unknown',\n    SPEC_SHA256: input.spec_sha256 ?? sha256File(specPath),\n    INTENT_PATH: path.join(dir, INTENT_FILE),\n    SPEC_PATH: specPath,\n    BUILD_PATH: buildPath,\n    SPEC_IDS: ids.join(','),\n    SPRINT_DIR: dir,\n    REPO_RULES: repoRules(input.repo_profile),\n  });\n\n  // 旧产物会被当成新产物，先删\n  fs.rmSync(buildPath, { force: true });\n  const before = {\n    head: headBefore,\n    branch: await currentBranch(worktree),\n    remote: await remoteSnapshot(worktree),\n    changes: await snapshotChanges(worktree),\n  };\n  // 运行前就查不到远端，事后无从比对：不启动 claude\n  if (before.remote === null) return fail('retryable', 'remote_check_failed', { evidence: [{ remote_before: null }] });\n\n  const args = ['-p', prompt, '--permission-mode', 'acceptEdits', ...CLAUDE_TOOLS];\n  const timeoutMs = claudeTimeoutMs(input.budget, TIMEOUT);\n  const run = await runClaude({ args, cwd: worktree, timeoutMs, tag: 'build', isolateRemote: true });\n  spend.usd = sumCostUsd(spend.usd, run.cost_usd);\n  const failure = claudeFailure(run) ?? (await guardFailure({ worktree, dir, sprintDir, input, before }));\n  if (failure) return failure;\n\n  if (!fs.existsSync(buildPath)) return fail('fatal', 'build_report_missing');\n  const errors = reportErrors(fs.readFileSync(buildPath, 'utf8'), { taskId: input.task_id, step: 'build', coversFile: SPEC_FILE, ids });\n  if (errors.length > 0) return fail('fatal', 'build_report_invalid', { evidence: [{ errors }] });\n  const headAfterBuild = await headSha(worktree);\n  if (headAfterBuild === headBefore) return fail('fatal', 'build_no_commit');\n  const post = await postFailure({ worktree, sprintDir, before });\n  if (post) return post;\n\n  const precheck = await precheckLoop({ worktree, dir, sprintDir, input, before });\n  if (precheck.failure) return precheck.failure;\n  const commits = (await gitOut(worktree, ['rev-list', '--reverse', `${headBefore}..HEAD`]) ?? '').split('\\n').filter(Boolean);\n\n  return {\n    status: 'completed',\n    outputs: { build_file: BUILD_FILE, build_commits: commits, candidate_sha: await headSha(worktree), build_sha256: sha256File(buildPath), ci_precheck: precheck.summary },\n    evidence: [`${BUILD_FILE} 已生成，${commits.length} 个提交；CI 门禁预检${precheck.summary.passed ? '通过' : `未过：${precheck.summary.failures.join('、')}`}`],\n  };\n}\n\n// 会话花费进 metrics（审计 #35）：本活动所有 claude 会话累加，成功失败都计\nawait runActivity(async (input) => {\n  const result = await main(input);\n  return { ...result, metrics: { ...(result?.metrics ?? {}), cost_usd: spend.usd } };\n}, { stage: 'build', entry: import.meta.url });\n",
  "packages/brain/scripts/coding-workflow/activities/chain-check.mjs": "// chain_check 活动：校验 <sprint_dir> 下 md 链（task_id/step 一致、upstream 锚点真实存在且覆盖上游）。\n// 应存在的链文件取自上下文 intent_file/spec_file/review_file/build_file/evidence_file；都没有时按只有 01/02 的旧链校验。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { loadBaselineContext } from '../lib/baseline-context.mjs';\nimport { parseMaterialPlan, materialPlanErrors } from '../lib/spec-materials.mjs';\nimport { specIds, qaScenarios } from '../lib/spec-check.mjs';\nimport { sha256File, chainTamperFailure } from '../lib/guards.mjs';\nimport { checkMaterialSync, parseMaterialRecord } from '../lib/material-sync.mjs';\nimport { runActivity, validateBase, fail } from '../lib/protocol.mjs';\nimport { checkChain } from '../lib/md-chain.mjs';\n\nconst CONTEXT_KEYS = ['intent_file', 'spec_file', 'review_file', 'build_file', 'evidence_file'];\n\nfunction materialCheck(input, dir) {\n  const tampered = chainTamperFailure(dir, input);\n  if (tampered) return { failure: tampered };\n  let baseline;\n  try { baseline = loadBaselineContext(input); }\n  catch (error) { return { failure: fail('fatal', 'material_sync_invalid', { evidence: [{ errors: [error.message] }] }) }; }\n  if (baseline.status !== 'managed') return {};\n  const sync = { status: 'failed', verification_scope: 'git_tree_and_receipt_bindings', object_id: baseline.object_id, base_sha: baseline.base_sha, candidate_sha: input.candidate_sha ?? 'unknown',\n    spec_sha256: input.spec_sha256 ?? null, build_sha256: input.build_sha256 ?? null, baseline_refs: baseline.refs.map(({ content, ...ref }) => ref), materials: [], unmapped_changes: [], unresolved: [] };\n  const reject = (errors) => ({ failure: fail('fatal', 'material_sync_invalid', { outputs: { material_sync: { ...sync, unresolved: errors } }, evidence: [{ errors }] }) });\n  if (!/^[a-f0-9]{64}$/.test(input.spec_sha256 ?? '') || !/^[a-f0-9]{64}$/.test(input.build_sha256 ?? '')) return reject(['material_hash_binding_missing']);\n  const buildPath = path.join(dir, '03-build.md');\n  const stat = fs.existsSync(buildPath) ? fs.lstatSync(buildPath) : null;\n  if (!stat?.isFile() || stat.isSymbolicLink() || sha256File(buildPath) !== input.build_sha256) return { failure: fail('fatal', 'chain_tampered', { evidence: [{ tampered_files: ['03-build.md'] }] }) };\n  try {\n    const text = fs.readFileSync(path.join(dir, '02-spec.md'), 'utf8');\n    const validation = materialPlanErrors(text, { baseline, intentIds: input.intent_ids, specIds: specIds(text), qaIds: qaScenarios(text).map((q) => q.id) });\n    if (validation.length) return reject(validation);\n    const plan = parseMaterialPlan(text);\n    plan.materials = plan.materials.map((row) => ({ ...row, kind: baseline.refs.find((ref) => ref.ref_id === row.ref_id)?.kind }));\n    const checked = checkMaterialSync({ worktree: input.worktree, baseSha: baseline.base_sha, candidateSha: input.candidate_sha,\n      taskId: input.task_id, runTag: input.run_tag, specSha: input.spec_sha256, sprintDir: input.sprint_dir, plan,\n      record: parseMaterialRecord(fs.readFileSync(path.join(dir, '03-build.md'), 'utf8')) });\n    Object.assign(sync, { materials: checked.materials, unmapped_changes: checked.unmapped_changes });\n    if (checked.errors.length) return reject(checked.errors);\n    return { material_sync: { ...sync, status: 'verified', unresolved: [] } };\n  } catch (error) { return reject([error.message]); }\n}\n\nawait runActivity(async (input) => {\n  // 校验失败直接抛错，由 runActivity 转成 failed/fatal（task_id_missing / sprint_dir_invalid）\n  const { dir } = validateBase(input);\n  const taskId = input.task_id;\n\n  const declared = CONTEXT_KEYS.map((k) => input[k]).filter((f) => typeof f === 'string' && f !== '');\n  const { ok, errors, files } = checkChain({ dir, taskId, ...(declared.length > 0 ? { files: declared } : {}) });\n  if (!ok) {\n    return fail('fatal', 'md_chain_invalid', { evidence: [{ errors }] });\n  }\n  const material = materialCheck(input, dir);\n  if (material.failure) return material.failure;\n  return { status: 'completed', outputs: { chain_files: files, ...(material.material_sync ? { material_sync: material.material_sync } : {}) } };\n});\n",
  "packages/brain/scripts/coding-workflow/activities/report.mjs": "// report 活动：把 PR 等交付信息 PATCH 回 Brain 任务的 result.coding_workflow。\n// 只传 result、不传 status（Brain 的 result 是 jsonb 顶层合并，不会覆盖已有的 handoff 等字段）。\n// 链在 verify 失败（没有 PR）时，把 verification 失败结论回写到 result.coding_workflow。\nimport os from 'node:os';\nimport { handoffFields, mergeWorkflow, containsFields, reportOutcome } from '../lib/material-handoff.mjs';\nimport { runActivity, fail, log } from '../lib/protocol.mjs';\n\nconst DEFAULT_BRAIN_URL = 'http://localhost:5221';\nconst REQUEST_TIMEOUT_MS = 20000;\n\n/** 失败响应的诊断信息：HTTP 状态 + 响应体 JSON 里的 code 字段（解析失败或没有则省略）。 */\nasync function httpEvidence(res) {\n  const evidence = { http_status: res.status };\n  try {\n    const code = (await res.json())?.code;\n    if (typeof code === 'string' || typeof code === 'number') evidence.body_code = code;\n  } catch {\n    // 响应体不是 JSON：只留 http_status\n  }\n  return evidence;\n}\n\nasync function httpFailure(res) {\n  const evidence = [await httpEvidence(res)];\n  if (res.status === 404 || res.status === 400) return fail('fatal', 'task_not_found', { evidence });\n  if (res.status >= 500 || res.status === 429 || res.status === 408) return fail('retryable', 'brain_unavailable', { evidence });\n  return fail('fatal', `brain_http_${res.status}`, { evidence });\n}\n\nconst isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);\n\n/** 合同对抗摘要与升级记录（有才带）：coding commander 从 Brain 的 result.coding_workflow 读取并处理升级。 */\nconst ganFields = (input) => ({\n  ...(isPlainObject(input.gan) ? { gan: input.gan } : {}),\n  ...(Array.isArray(input.escalations) && input.escalations.length > 0 ? { escalations: input.escalations } : {}),\n});\n\n/**\n * 回写内容：有 pr_url → 交付信息（有 verification 一并带上）；\n * 没有 pr_url 但有 verification（链在验收处失败）→ 失败结论；两者都没有返回 null。\n */\nfunction codingWorkflowResult(input) {\n  const verification = isPlainObject(input.verification) ? input.verification : undefined;\n  if (typeof input.pr_url === 'string' && input.pr_url !== '') {\n    return {\n      pr_url: input.pr_url,\n      branch: input.branch,\n      sprint_dir: input.sprint_dir,\n      chain_files: input.chain_files,\n      run_tag: input.run_tag,\n      host: os.hostname(),\n      ...(verification ? { verification } : {}),\n      ...ganFields(input),\n    };\n  }\n  if (input.material_sync?.status === 'failed') return { status: 'failed', run_tag: input.run_tag, sprint_dir: input.sprint_dir, ...ganFields(input) };\n  if (verification) return { status: 'failed', run_tag: input.run_tag, sprint_dir: input.sprint_dir, verification, ...ganFields(input) };\n  return null;\n}\n\nawait runActivity(async (input) => {\n  // 不碰文件系统，只需要 task_id；既无 pr_url 又无失败结论说明前序没走到可回写的地步，不发请求\n  const taskId = input.task_id;\n  if (typeof taskId !== 'string' || taskId === '') return fail('fatal', 'task_id_missing');\n  const codingWorkflow = codingWorkflowResult(input);\n  if (!codingWorkflow) return fail('fatal', 'pr_url_missing');\n\n  const base = String(input.brain_url || DEFAULT_BRAIN_URL).replace(/\\/+$/, '');\n  const url = `${base}/api/brain/tasks/${encodeURIComponent(taskId)}`;\n  const signal = AbortSignal.timeout(REQUEST_TIMEOUT_MS);\n\n  try {\n    const readBefore = await fetch(url, { signal });\n    if (!readBefore.ok) return httpFailure(readBefore);\n    const previous = await readBefore.json();\n    const handoff = handoffFields(input, previous?.result?.coding_workflow);\n    const outcome = reportOutcome(input, previous?.result?.coding_workflow, handoff);\n    const update = { ...codingWorkflow, ...handoff, ...outcome };\n    const merged = { ...mergeWorkflow(previous?.result?.coding_workflow, update), versions: update.versions, material_sync: update.material_sync, verification: update.verification };\n    const body = { result: { coding_workflow: merged } };\n    const res = await fetch(url, {\n      method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), signal,\n    });\n    if (!res.ok) return httpFailure(res);\n    // 独立读回，不能仅凭 PATCH 200 认定落账；同时确认原顶层字段未丢失。\n    const readAfter = await fetch(url, { signal });\n    if (!readAfter.ok) return httpFailure(readAfter);\n    const actual = await readAfter.json();\n    const expectedResult = { ...(previous?.result ?? {}), coding_workflow: merged };\n    if (!containsFields(actual?.result, expectedResult)) return fail('fatal', 'report_readback_mismatch');\n\n  } catch (error) {\n    log(`[report] 读写/核验 ${url} 失败: ${error?.message || error}`);\n    return fail('retryable', 'brain_unavailable');\n  }\n\n  const what = codingWorkflow.pr_url ?? `核验失败 ${codingWorkflow.verification?.reason_code ?? input.material_sync?.status ?? 'unknown'}`;\n  return {\n    status: 'completed',\n    outputs: { reported: true },\n    evidence: [`已回写并独立读回 Brain 任务 ${taskId}：${what}`],\n  };\n});\n",
  "packages/brain/scripts/coding-workflow/contract.json": "{\n  \"workflow\": \"coding_spec\",\n  \"activities\": [\n    {\n      \"key\": \"intent\",\n      \"order\": 1,\n      \"budget\": { \"max_duration_s\": 60, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"brain_unavailable\"],\n        \"needs_human\": { \"cases\": [\"acceptance_missing\"] },\n        \"fatal\": [\"task_id_missing\", \"sprint_dir_invalid\", \"task_not_found\"]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"setup\",\n        \"entry\": \"activities/intent.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 1\n      }\n    },\n    {\n      \"key\": \"spec\",\n      \"order\": 2,\n      \"budget\": { \"max_duration_s\": 900, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"claude_failed\", \"claude_timeout\", \"spec_invalid\"],\n        \"needs_human\": { \"cases\": [\"codex_auth\", \"codex_configuration\", \"claude_auth\", \"qa_mode_unsupported\"] },\n        \"fatal\": [\"sprint_dir_invalid\", \"task_id_missing\", \"intent_ids_missing\", \"intent_ids_invalid\", \"spec_missing\", \"spec_out_of_scope_write\", \"chain_tampered\", \"baseline_invalid\"]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"source\",\n        \"entry\": \"activities/spec.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 2\n      }\n    },\n    {\n      \"key\": \"spec_review\",\n      \"order\": 3,\n      \"budget\": { \"max_duration_s\": 21600, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"claude_failed\", \"claude_timeout\", \"spec_invalid\", \"response_missing\"],\n        \"needs_human\": { \"cases\": [\"codex_auth\", \"codex_configuration\", \"claude_auth\"] },\n        \"fatal\": [\n          \"task_id_missing\",\n          \"sprint_dir_invalid\",\n          \"intent_ids_missing\",\n          \"intent_ids_invalid\",\n          \"chain_tampered\",\n          \"spec_missing\",\n          \"spec_review_out_of_scope_write\",\n          \"baseline_invalid\",\n          \"review_invalid\",\n          \"gan_budget_exceeded\"\n        ]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"source\",\n        \"entry\": \"activities/spec-review.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 1\n      }\n    },\n    {\n      \"key\": \"build\",\n      \"order\": 4,\n      \"budget\": { \"max_duration_s\": 3600, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"claude_failed\", \"claude_timeout\", \"remote_check_failed\", \"git_check_failed\"],\n        \"needs_human\": { \"cases\": [\"codex_auth\", \"codex_configuration\", \"claude_auth\"] },\n        \"fatal\": [\n          \"sprint_dir_invalid\",\n          \"task_id_missing\",\n          \"spec_missing\",\n          \"spec_ids_missing\",\n          \"git_head_unavailable\",\n          \"build_report_missing\",\n          \"build_no_commit\",\n          \"build_uncommitted\",\n          \"chain_tampered\",\n          \"remote_changed\",\n          \"build_history_rewritten\",\n          \"build_touched_agent_config\",\n          \"build_report_invalid\",\n          \"build_sprint_polluted\"\n        ]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"source\",\n        \"entry\": \"activities/build.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 1\n      }\n    },\n    {\n      \"key\": \"verify\",\n      \"order\": 5,\n      \"budget\": { \"max_duration_s\": 1200, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"claude_failed\", \"claude_timeout\", \"remote_check_failed\"],\n        \"needs_human\": { \"cases\": [\"codex_auth\", \"codex_configuration\", \"claude_auth\"] },\n        \"fatal\": [\n          \"sprint_dir_invalid\",\n          \"task_id_missing\",\n          \"intent_ids_missing\",\n          \"intent_ids_invalid\",\n          \"evidence_missing\",\n          \"evidence_invalid\",\n          \"evidence_incomplete\",\n          \"verification_failed\",\n          \"verify_out_of_scope_write\",\n          \"verify_head_moved\",\n          \"chain_tampered\",\n          \"remote_changed\",\n          \"evidence_unverified\",\n          \"build_report_restore_failed\"\n        ]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"batch_end\",\n        \"entry\": \"activities/verify.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 1\n      }\n    },\n    {\n      \"key\": \"chain_check\",\n      \"order\": 6,\n      \"budget\": { \"max_duration_s\": 30, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [],\n        \"needs_human\": { \"cases\": [] },\n        \"fatal\": [\"md_chain_invalid\", \"sprint_dir_invalid\", \"task_id_missing\", \"material_sync_invalid\", \"chain_tampered\"]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"batch_end\",\n        \"entry\": \"activities/chain-check.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 1\n      }\n    },\n    {\n      \"key\": \"publish\",\n      \"order\": 7,\n      \"budget\": { \"max_duration_s\": 900, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"push_failed\", \"gh_failed\"],\n        \"needs_human\": { \"cases\": [\"gh_auth\"] },\n        \"fatal\": [\n          \"sprint_dir_invalid\",\n          \"task_id_missing\",\n          \"chain_files_missing\",\n          \"gp_anchor_invalid\",\n          \"branch_invalid\",\n          \"git_add_failed\",\n          \"git_commit_failed\",\n          \"git_diff_failed\"\n        ]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"batch_end\",\n        \"entry\": \"activities/publish.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 1\n      }\n    },\n    {\n      \"key\": \"report\",\n      \"order\": 8,\n      \"budget\": { \"max_duration_s\": 30, \"heartbeat_s\": 30 },\n      \"failure\": {\n        \"empty_ok\": [],\n        \"retryable\": [\"brain_unavailable\"],\n        \"needs_human\": { \"cases\": [] },\n        \"fatal\": [\"pr_url_missing\", \"task_id_missing\", \"task_not_found\", \"report_readback_mismatch\"]\n      },\n      \"runtime\": {\n        \"protocol\": \"json-stdio-v1\",\n        \"phase\": \"finalize\",\n        \"entry\": \"activities/report.mjs\",\n        \"on_failure\": \"stop_run\",\n        \"max_attempts\": 2\n      }\n    }\n  ]\n}\n",
  "packages/brain/scripts/coding-workflow/lib/material-handoff.mjs": "// 候选材料与生命周期事实分开：本步骤不能证明 GitHub 合并或生产部署。\nexport const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);\nconst revision = (value) => /^[a-f0-9]{40}$/.test(value ?? '') ? value : 'unknown';\nexport function handoffFields(input, previous = {}) {\n  const candidate = revision(input.candidate_sha);\n  const ids = input.intent_ids;\n  const failed = input.material_sync?.status === 'failed' || input.verification?.status === 'failed';\n  const verified = input.material_sync?.status !== 'failed' && input.verification?.status !== 'failed' && candidate !== 'unknown' && Array.isArray(ids) && ids.length > 0\n    && Array.isArray(input.verified_ids) && ids.every((id) => input.verified_ids.includes(id));\n  const old = previous?.versions;\n  const sameCandidate = candidate !== 'unknown' && old?.candidate === candidate;\n  const history = Array.isArray(previous?.version_history) ? [...previous.version_history] : [];\n  if (isObject(old) && !sameCandidate && !history.some((item) => JSON.stringify(item) === JSON.stringify(old))) history.push(old);\n  return {\n    ...(history.length ? { version_history: history } : {}),\n    material_sync: isObject(input.material_sync) ? input.material_sync : sameCandidate && isObject(previous.material_sync) ? previous.material_sync : { status: 'unknown', unresolved: ['legacy_unconfigured'] },\n    versions: { baseline: revision(input.initial_base_sha) !== 'unknown' ? revision(input.initial_base_sha) : sameCandidate ? revision(old.baseline) : 'unknown', candidate, verified: verified ? candidate : sameCandidate && !failed && input.verified_ids === undefined && input.verification === undefined ? revision(old.verified) : 'unknown', merged: sameCandidate ? old.merged ?? 'unknown' : 'unknown', deployed: sameCandidate ? old.deployed ?? 'unknown' : 'unknown' },\n  };\n}\n\n// Brain PATCH 的 result 只做顶层合并；提前读取并合并 coding_workflow 内已有的其他字段。\n// 这不是跨写者的原子CAS：同任务并发写者仍须由既有执行租约排他。\nexport function mergeWorkflow(previous, update) {\n  const out = isObject(previous) ? { ...previous } : {};\n  for (const [key, value] of Object.entries(update)) {\n    if (value === undefined) continue;\n    out[key] = isObject(value) ? mergeWorkflow(out[key], value) : value;\n  }\n  return out;\n}\nexport function containsFields(actual, expected) {\n  if (Array.isArray(expected)) return Array.isArray(actual) && actual.length === expected.length && expected.every((v, i) => containsFields(actual[i], v));\n  if (isObject(expected)) return isObject(actual) && Object.entries(expected).every(([key, value]) => containsFields(actual[key], value));\n  return actual === expected;\n}\n\n// 当前结论整体替换；历史验证保留原字段，但不能混入另一候选的当前判断。\nexport function reportOutcome(input, previous, handoff) {\n  const same = handoff.versions.candidate !== 'unknown' && handoff.versions.candidate === previous?.versions?.candidate;\n  const verification = isObject(input.verification) ? input.verification\n    : handoff.versions.verified !== 'unknown' ? { status: 'passed', candidate_sha: handoff.versions.candidate, ...(Array.isArray(input.verified_ids) ? { verified_ids: input.verified_ids } : {}) }\n    : same && input.verified_ids === undefined && isObject(previous?.verification) ? previous.verification : { status: 'unknown' };\n  const history = Array.isArray(previous?.report_history) ? [...previous.report_history] : [];\n  if (isObject(previous?.verification) && (!same || JSON.stringify(previous.verification) !== JSON.stringify(verification))) {\n    const item = { candidate: revision(previous?.versions?.candidate), ...(previous.run_tag ? { run_tag: previous.run_tag } : {}), ...(previous.status ? { status: previous.status } : {}), verification: previous.verification };\n    if (!history.some(row => JSON.stringify(row) === JSON.stringify(item))) history.push(item);\n  }\n  return { status: verification.status === 'failed' || handoff.material_sync.status === 'failed' || !input.pr_url ? 'failed' : 'completed', verification, ...(history.length ? { report_history: history } : {}) };\n}\n",
  "packages/brain/scripts/coding-workflow/lib/material-sync.mjs": "// 只读取固定 Git 树：模型的03记录是待核对声明，不是判定依据。\nimport crypto from 'node:crypto';\nimport { execFileSync } from 'node:child_process';\n\nconst SHA = /^[a-f0-9]{40}$/;\nconst pathValid = (p) => typeof p === 'string' && p.length > 0 && p.length <= 512\n  && !/^[/:]|[\\\\\\x00-\\x1f]/.test(p) && !p.split('/').some((x) => !x || ['.', '..', '.git'].includes(x));\nconst digest = (bytes) => crypto.createHash('sha256').update(bytes).digest('hex');\nfunction git(repo, args, encoding = 'utf8') {\n  const env = { ...process.env, GIT_NO_REPLACE_OBJECTS: '1' };\n  for (const key of ['GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE']) delete env[key];\n  return execFileSync('git', ['--literal-pathspecs', '-C', repo, ...args], { encoding, env, maxBuffer: 8 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] });\n}\nfunction entry(repo, revision, file) {\n  const line = git(repo, ['ls-tree', '-z', revision, '--', file]).split('\\0')[0];\n  if (!line) return null;\n  const match = /^(\\d+) (\\w+) ([a-f0-9]{40})\\t/.exec(line);\n  if (!match || !['100644', '100755'].includes(match[1]) || match[2] !== 'blob') return { invalid: true };\n  return { mode: match[1], oid: match[3], digest: digest(git(repo, ['cat-file', 'blob', match[3]], 'buffer')) };\n}\nconst keyOf = (row) => `${row?.ref_id}\\0${row?.path}`;\nconst nonempty = (s) => typeof s === 'string' && s.trim().length > 0;\n\nexport function parseMaterialRecord(text) {\n  const sections = String(text).split(/^## 材料同步记录\\s*$/m);\n  if (sections.length !== 2) throw new Error('material_record_missing_or_duplicate');\n  const body = sections[1].split(/^#{1,2}\\s/m)[0];\n  const blocks = [...body.matchAll(/^```json\\s*\\n([\\s\\S]*?)^```\\s*$/gm)];\n  if (blocks.length !== 1) throw new Error('material_record_json_missing_or_duplicate');\n  try { return JSON.parse(blocks[0][1]); } catch { throw new Error('material_record_json_invalid'); }\n}\n\nexport function checkMaterialSync({ worktree, baseSha, candidateSha, taskId, runTag, specSha, sprintDir, plan, record }) {\n  const errors = [];\n  const materials = [];\n  let changed = [];\n  if (!SHA.test(baseSha ?? '')) errors.push('material_base_missing');\n  if (!SHA.test(candidateSha ?? '')) errors.push('material_candidate_missing');\n  if (errors.length) return { errors, materials, unmapped_changes: [] };\n  try {\n    if (git(worktree, ['rev-parse', 'HEAD']).trim() !== candidateSha) errors.push('material_candidate_moved');\n    try { git(worktree, ['merge-base', '--is-ancestor', baseSha, candidateSha]); }\n    catch { errors.push('material_base_not_ancestor'); }\n    changed = git(worktree, ['diff', '--name-only', '-z', '--no-renames', baseSha, candidateSha]).split('\\0').filter(Boolean);\n    const trackedDirty = git(worktree, ['diff', '--name-only', '-z', 'HEAD']).split('\\0').filter(Boolean);\n    const untracked = git(worktree, ['ls-files', '--others', '--exclude-standard', '-z']).split('\\0').filter(Boolean);\n    const outsideSprint = (file) => !sprintDir || !(file === sprintDir || file.startsWith(`${sprintDir}/`));\n    if ([...trackedDirty, ...untracked].some(outsideSprint)) errors.push('material_worktree_dirty');\n  } catch { errors.push('material_git_unavailable'); }\n  if (!record || record.version !== 1 || !Array.isArray(record.materials)) errors.push('material_record_invalid');\n  for (const [field, expected, code] of [['task_id', taskId, 'task'], ['run_tag', runTag, 'run'], ['base_sha', baseSha, 'base'], ['candidate_sha', candidateSha, 'candidate'], ['spec_sha256', specSha, 'spec']]) {\n    if (!nonempty(expected) || record?.[field] !== expected) errors.push(`material_record_${code}_mismatch`);\n  }\n  if (plan?.version !== 1 || !Array.isArray(plan?.materials) || !plan.materials.length) return { errors: [...errors, 'material_plan_invalid'], materials, unmapped_changes: changed };\n  const rows = plan.materials.flatMap((row) => [row, ...(row.additional_changes ?? []).map((extra) => ({ ...row, ...extra, ref_id: row.ref_id, kind: row.kind, approval_refs: row.approval_refs, additional_changes: undefined }))]);\n  const seen = new Set();\n  const actions = new Map();\n  const declared = new Map();\n  for (const item of record?.materials ?? []) {\n    const key = keyOf(item);\n    if (declared.has(key)) errors.push(`material_record_duplicate:${item.path}`);\n    declared.set(key, item);\n  }\n  for (const row of rows) {\n    if (!pathValid(row.path)) { errors.push('material_path_invalid'); continue; }\n    const start = errors.length;\n    if (actions.has(row.path) && actions.get(row.path) !== row.action) errors.push(`material_path_conflict:${row.path}`);\n    actions.set(row.path, row.action);\n    seen.add(row.path);\n    const claim = declared.get(keyOf(row));\n    if (!claim) errors.push(`material_record_missing:${row.path}`);\n    else if (claim.action !== row.action || ![claim.verification, claim.command, claim.output].every(nonempty)) errors.push(`material_record_incomplete:${row.path}`);\n    if (!['keep', 'update', 'retire', 'not_applicable'].includes(row.action)) errors.push(`material_action_unresolved:${row.path}`);\n    if ((row.action === 'retire' || row.action === 'update' && row.kind === 'sample') && !row.approval_refs?.length) errors.push(`material_approval_missing:${row.path}`);\n    let before, after;\n    try {\n      before = entry(worktree, baseSha, row.path);\n      after = entry(worktree, candidateSha, row.path);\n      if (before?.invalid || after?.invalid) errors.push(`material_non_regular:${row.path}`);\n    } catch { errors.push(`material_unreadable:${row.path}`); }\n    const isChanged = before?.oid !== after?.oid || before?.mode !== after?.mode;\n    if (['keep', 'not_applicable'].includes(row.action) && isChanged) errors.push(`material_keep_changed:${row.path}`);\n    if (row.action === 'update' && !isChanged) errors.push(`material_update_missing:${row.path}`);\n    if (row.action === 'update' && !after) errors.push(`material_update_deleted:${row.path}`);\n    if (row.action === 'retire' && (!before || after)) errors.push(`material_retire_not_deleted:${row.path}`);\n    if (row.action === 'keep' && !before) errors.push(`material_keep_missing:${row.path}`);\n    materials.push({ ref_id: row.ref_id, path: row.path, action: row.action, changed: isChanged,\n      status: errors.length === start ? 'verified' : 'failed', before_digest: before?.digest ?? null, after_digest: after?.digest ?? null });\n  }\n  for (const claim of record?.materials ?? []) if (!rows.some((r) => keyOf(r) === keyOf(claim))) errors.push(`material_record_unknown:${claim.path}`);\n  const unmapped_changes = changed.filter((file) => !seen.has(file));\n  errors.push(...unmapped_changes.map((file) => `material_unplanned_change:${file}`));\n  return { errors: [...new Set(errors)], materials, unmapped_changes };\n}\n",
  "packages/brain/scripts/coding-workflow/prompts/build.md": "你是 coding workflow 的 build 步骤执行者。请在原任务授权范围内完成实现规格并提交。输出必须使用简体中文。\n\n输入信息（以下六行为机器可读，原样保留）：\nTASK_ID: {{TASK_ID}}\nINTENT_PATH: {{INTENT_PATH}}\nSPEC_PATH: {{SPEC_PATH}}\nBUILD_PATH: {{BUILD_PATH}}\nSPEC_IDS: {{SPEC_IDS}}\nSPRINT_DIR: {{SPRINT_DIR}}\nRUN_TAG: {{RUN_TAG}}\nINITIAL_BASE_SHA: {{INITIAL_BASE_SHA}}\nSPEC_SHA256: {{SPEC_SHA256}}\n\n步骤：\n1. 先读取 INTENT_PATH 中的原任务、允许改动范围与禁止项，再读取 SPEC_PATH，理解每条规格（锚点 `### S-n`，SPEC_IDS 列出了全部 S-n）。任一输入缺失或不可读时停止修改，如实报告；不得猜测授权范围。\n2. 对每条 S-n 在任务与规格允许的范围内先验证失败、再实现、再验证通过。只有任务与规格允许修改测试文件时才新增或修改仓库测试；任务禁止测试文件或只允许文档时，使用允许的临时 artifact 或内联命令对真实结果作可失败断言，不新增或提交仓库测试。任务的显式范围与禁止项优先于通用 TDD、测试固化和技能模板；不得为了测试或门禁扩大改动范围。\n3. 在当前分支上 `git commit` 提交任务与规格允许的改动（可以多个提交）。提交前逐项核对实际 diff（含新增文件）与原任务边界，并确认没有本次遗留的未提交改动；临时验证材料不得混入提交。\n4. 最后只写 BUILD_PATH 这一个总结文件（不要提交它）。\n\nBUILD_PATH 文件格式要求：\n- 以 frontmatter 开头，三个键各占一行，写法如下（upstream 为单行 JSON 数组，必须列出 SPEC_IDS 中的全部 S-n，每项形如 `02-spec.md#S-1`）：\n\n```\n---\ntask_id: {{TASK_ID}}\nstep: build\nupstream: [\"02-spec.md#S-1\"]\n---\n```\n\n- 正文每条用标题行 `### B-n`（n 从 1 递增），每条写明：对应的 S-n、改动的文件、采用的验证方式、实际运行的命令与输出摘要、提交 SHA；说明验证方式如何遵守原任务范围，不要求新增测试文件。\n\n约束：\n- 不 push，不开 PR，不调用 gh。\n- 不修改 SPRINT_DIR 里除 BUILD_PATH 以外的任何文件；SPRINT_DIR 下的文件一律不要提交（不要用 `git add -A` / `git add .`，只 add 原任务与规格允许的具体改动路径）。\n- 只在当前分支上追加新提交：不 amend、不 reset、不 rebase、不切换分支。\n- 不修改 `.claude/` 目录、`CLAUDE.md`、`AGENTS.md`。\n- 测试命令与输出摘要必须是真实运行得到的，不要编造。\n\n本仓库的 CI 规矩如下（提交后程序会在本地先跑一遍这些门禁，没过会要求你修；一次写对最省事）：\n\n{{REPO_RULES}}\n\n受管对象的材料同步：\n- 02 有 `## 旧规则与材料计划` 时，按每条 materials 及 additional_changes 实施；keep 不改、update 必须有实际更新、retire 必须删除，conflict 不能自行放宽。\n- 在 03 追加唯一 `## 材料同步记录`，其下唯一 json 围栏：\n  `{\"version\":1,\"task_id\":\"当前 TASK_ID\",\"run_tag\":\"当前 RUN_TAG\",\"base_sha\":\"INITIAL_BASE_SHA\",\"candidate_sha\":\"最终 git rev-parse HEAD\",\"spec_sha256\":\"SPEC_SHA256\",\"materials\":[{\"ref_id\":\"登记ID\",\"path\":\"实际路径\",\"action\":\"与02一致\",\"verification\":\"验证方式\",\"command\":\"实际运行命令\",\"output\":\"实际输出摘要\"}]}`。\n- 主材料和额外文件各一行，保留项也写明验证依据；记录必须绑定最终候选，不使用旧报告或别的任务结果。字段齐全不等于语义正确，独立审查仍核对内容。\n- 这些记录是待核验声明；可信 chain-check 会重读固定 base 与 candidate 的真实树和03摘要。不要在03把自己声明为已合并或已部署。\n",
  "packages/brain/scripts/coding-workflow/prompts/ci-precheck-fix.md": "你是开发方。你刚按规格写完代码并提交，推上 GitHub 之前，程序在本地跑了一遍 CI 的规矩类门禁，下面这些没过——推上去必然被 CI 打红。当前目录就是仓库，在分支 {{BRANCH}} 上。输出必须使用简体中文。\n\n输入信息（以下各行为机器可读，原样保留）：\nROLE: ci_precheck_fix\nSPRINT_DIR: {{SPRINT_DIR}}\nINTENT_PATH: {{INTENT_PATH}}\nSPEC_PATH: {{SPEC_PATH}}\nBUILD_PATH: {{BUILD_PATH}}\n\n没过的门禁与日志：\n{{FAILURES}}\n\n常见门禁的要求见下方「本仓库规矩」（门禁脚本在 .github/workflows/scripts/ 下，看不懂日志就读脚本）；分支名和改动规模问题无法靠改代码解决时，在最终回复里说明原因即可，不要做无关改动。\n\n要求：\n1. 只修上面列出的门禁问题，不借机做无关改动，不改变已实现的业务行为。\n2. 提交到当前分支（可以多个提交），提交信息用 `fix(...)`/`test(...)` 等开头的中文说明。\n3. 修完后自己再跑一次对应的门禁脚本确认通过（例如 `bash .github/workflows/scripts/lint-test-pairing.sh origin/main`）。\n4. SPRINT_DIR 内仅允许更新 03-build.md（BUILD_PATH）：记入本轮真实修复提交与验证输出。若有 `## 材料同步记录`，保留 task/run/base/spec 绑定，candidate_sha 改为最终真实 HEAD，并同步受影响材料的实际命令与输出。不要提交03；旧记录不能冒充新候选证据。\n\n禁止：\n- 不修改 SPRINT_DIR 下除上述 03-build.md 以外的任何文件，不提交任何 sprint 文件；不修改 .claude/、CLAUDE.md、AGENTS.md，不修改 runner 生成的 QA 回归 smoke（cw-*-qa-smoke.sh，在哪见下方本仓库规矩；由 runner 按 QA 报告固化，勿手改）。\n- 不删除或放宽已有测试的断言来\"让它通过\"。\n- 不 push、不调用 gh、不改写已有提交（不 amend、不 rebase、不 reset）。\n- 结束时除允许的03报告外，工作区必须干净（没有未提交改动）。\n\n{{REPO_RULES}}\n",
  "packages/brain/scripts/coding-workflow/runner/__tests__/fixtures/executor-ipc-preload.mjs": "// 测试专用：只给明确的假执行器接通父 runner 的测试 fetch，真实执行器不拦截。\nimport childProcess from 'node:child_process';\nimport { syncBuiltinESMExports } from 'node:module';\nconst params = new URL(import.meta.url).searchParams;\nconst entries = new Set([params.get('executor'), ...params.getAll('activity')].filter(Boolean));\nconst fetchPreload = params.get('fetchPreload');\nconst namespace = 'coding-test-brain-v1';\nconst originalSpawn = childProcess.spawn;\nchildProcess.spawn = function (bin, args, options) {\n  if (bin !== process.execPath || !entries.has(args?.[0])) return originalSpawn(bin, args, options);\n  const child = originalSpawn(bin, ['--import', fetchPreload, '--import', import.meta.url, ...args], {\n    ...options, stdio: [...options.stdio.slice(0, 3), 'ipc'],\n  });\n  const pending = new Map();\n  const send = (message) => { if (child.connected) child.send({ namespace, ...message }, () => {}); };\n  child.on('message', async (request) => {\n    if (request?.namespace !== namespace) return;\n    const { id, type } = request;\n    if (!Number.isSafeInteger(id) || id < 1) return;\n    if (type === 'cancel') { pending.get(id)?.abort(); pending.delete(id); return; }\n    if (type !== 'fetch' || pending.has(id)) return;\n    const controller = new AbortController();\n    pending.set(id, controller);\n    try {\n      const response = await fetch(request.url, {\n        method: request.method, headers: request.headers,\n        ...(!['GET', 'HEAD'].includes(request.method) ? { body: request.body } : {}),\n        signal: controller.signal,\n      });\n      const body = await response.text();\n      if (pending.delete(id)) send({ type: 'response', id, status: response.status, headers: Object.fromEntries(response.headers), body });\n    } catch (error) {\n      if (pending.delete(id)) send({ type: 'error', id, error: error.message });\n    }\n  });\n  child.once('disconnect', () => { for (const controller of pending.values()) controller.abort(); pending.clear(); });\n  return child;\n};\nsyncBuiltinESMExports();\n"
};
const base='95d3d6b9647a4accc748a4988f6bcf151d82c55f',revision='5f200f508ead611d81acd491c403ba2a06c61633';
const git=(...a)=>execFileSync('git',a,{encoding:'utf8',maxBuffer:32e6});
const prefix='packages/brain/scripts/coding-workflow/';
const indexPath='docs/registry/coding-workflow-authority.json';
const index=JSON.stringify({object_id:'coding-workflow',refs:[['spec','runner/README.md'],['rule','prompts/repo-rules/cecelia.md'],['sample','__tests__/fixtures/activity-fixture.mjs'],['implementation','activities/intent.mjs']].map(([kind,path])=>({ref_id:kind,kind,path:prefix+path,required:true}))});
const fixture={...A_ENVELOPES.reviewed,...B_ENVELOPES.reviewed,...C,[indexPath]:index};
const paths=[...new Set([...git('ls-tree','-rz','--full-tree','--name-only',base).split('\0').filter(Boolean),...Object.keys(fixture)])];const cache=new Map();
const read=p=>{if(Object.hasOwn(fixture,p))return fixture[p];if(!cache.has(p))cache.set(p,git('show',base+':'+p));return cache.get(p)};
const context=(overrides={},missing=[])=>reviewedAContext({parse:t=>parse(t,{ecmaVersion:'latest',sourceType:'module'}),revision,paths:paths.filter(p=>!missing.includes(p)),readSource:p=>Object.hasOwn(overrides,p)?overrides[p]:read(p)});
async function collect(overrides={}){const out=await buildExistingOpsSources({scope:'cecelia-factory',repo:'perfectuser21/cecelia',revision,paths,readSource:p=>Object.hasOwn(overrides,p)?overrides[p]:read(p)});return out.consumers.find(c=>c.workflow_key==='factory_f3_ops')}
it('真实C完整组合通过且绑定全部C成员原字节',async()=>{const f=await collect();expect(f.status,JSON.stringify(f.gaps)).toBe('verified');for(const p of Object.keys(C))expect(f.bindings.find(b=>b.path===p)?.content_sha256,p).toBe(createHash('sha256').update(read(p)).digest('hex'))},120000);
for(const p of Object.keys(C))it('C完整组合缺项/变异拒绝 '+p,async()=>{expect(await context({},[p])).toBeNull();expect(await context({[p]:read(p)+'\nprocess.exit(0);'})).toBeNull()});
it('C不能混入旧A单executor relay',async()=>{const p=prefix+'runner/__tests__/fixtures/executor-ipc-preload.mjs';expect(await context({[p]:A_ENVELOPES.reviewed[p]})).toBeNull()});
it('C真实活动消费边完整且runtime-only不认领材料实现',async()=>{const c=await context();expect(c).not.toBeNull();const relations=[];await c.record({read,relations});for(const [consumer,input]of [['__tests__/chain-materials.test.mjs','activities/chain-check.mjs'],['__tests__/report-materials.test.mjs','activities/report.mjs'],['__tests__/build-materials.test.mjs','activities/build.mjs']])expect(relations.some(r=>r.consumer_path===prefix+consumer&&r.input_path===prefix+input)).toBe(true);const seen=[];await c.record({read:p=>{seen.push(p);return read(p)},relations:[],buildInputs:false});expect(seen).not.toContain(prefix+'lib/material-sync.mjs')});

it('C出现但B新增闭包整组缺失必须拒绝',async()=>{expect(await context({},Object.keys(B_ENVELOPES.reviewed).filter(p=>!Object.hasOwn(B_ENVELOPES.legacy,p)))).toBeNull()});
